// Liest /admin/list und /date/list vollstaendig und gibt ausschliesslich
// die fuer Trainerzuordnung erforderlichen, datenschutzarmen Felder weiter.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt.');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const basis = 'https://app1.edoobox.com/v2';

function rowsAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

async function holeAlle(pfad) {
  const alle = [];
  const reply = 2000;
  let start = 0;
  let total = null;
  for (let seite = 1; seite <= 20; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET', url: basis + pfad, headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true, returnFullResponse: true, timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
    if (!(a.statusCode >= 200 && a.statusCode < 300)) throw new Error(`${pfad}: HTTP ${a.statusCode}`);
    const rows = rowsAus(a.body);
    if (total === null && a.body?.limit?.total !== undefined) total = Number(a.body.limit.total);
    alle.push(...rows);
    start += rows.length;
    if (rows.length === 0 || rows.length < reply || (total !== null && start >= total)) break;
  }
  if (total !== null && alle.length !== total) throw new Error(`${pfad}: gemeldet ${total}, gelesen ${alle.length}`);
  return alle;
}

const adminRoh = await holeAlle.call(this, '/admin/list');
const dateRoh = await holeAlle.call(this, '/date/list');

const admins = adminRoh.map(a => ({
  admin_id: String(a.id),
  shortcut: a.shortcut || null,
  permission: a.permission || null,
  is_active: a.status === true,
}));

const dates = dateRoh.map(d => ({
  date_id: String(d.id),
  offer_id: String(d.offer),
  date_start: d.date_start || null,
  date_end: d.date_end || null,
  place_ref: d.place || null,
  room_ref: d.room || null,
  leaders: [...new Set((Array.isArray(d.leader) ? d.leader : []).filter(Boolean).map(String))],
}));

return [{ json: {
  schritt: 'S54',
  adminsJson: JSON.stringify(admins),
  datesJson: JSON.stringify(dates),
  admins: admins.length,
  dates: dates.length,
  leaders: dates.reduce((s, d) => s + d.leaders.length, 0),
} }];

// Zwei Erkundungen in einem Knoten:
//   1. Feldbestand von /v2/invoice/{id}/data fuer acht Rechnungen
//   2. gibt die Rechnungsliste erneut aus, damit die Datenbank vergleichen kann

const auth = $('S24 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abruf(pfad, qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2${pfad}`,
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abruf.bind(this);

function liste(h) {
  if (!h || typeof h !== 'object') return [];
  const d = h.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

function zahl(w) {
  if (w === null || w === undefined || w === '' || w === false) return null;
  const n = Number(String(w).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function zeitpunkt(w) {
  return typeof w === 'string' && /^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w) ? w : null;
}

// Alle Rechnungen einsammeln
const alle = [];
let start = 0;
for (let i = 0; i < 20; i += 1) {
  const a = await hole('/invoice/list', { 'limit[start]': start, 'limit[reply]': 2000 });
  if (a.statusCode !== 200) throw new Error(`invoice/list Status ${a.statusCode}`);
  const d = liste(a.body);
  alle.push(...d);
  if (d.length < 2000) break;
  start += 2000;
}

const saetze = alle.filter((r) => r && r.id).map((r) => ({
  invoice_id: String(r.id),
  paytrans: r.paytrans ? String(r.paytrans) : null,
  user_ref_roh: r.user ? String(r.user) : null,
  invoice_number: r.number ? String(r.number) : null,
  amount: zahl(r.amount),
  status: zahl(r.status),
  date_create: zeitpunkt(r.date_create),
  offer_start_date: zeitpunkt(r.offer_start_date),
}));

// Feldbestand der Einzelrechnung. Acht moeglichst verschiedene Faelle.
const proben = [];
for (const s of [1, 2, 3].map((n) => saetze.find((x) => x.status === n)).filter(Boolean)) proben.push(s);
for (const s of saetze.slice(-3)) if (!proben.includes(s)) proben.push(s);
for (const s of saetze) {
  if (proben.length >= 8) break;
  if (!proben.includes(s)) proben.push(s);
}

function art(w) {
  if (w === null) return 'null';
  if (Array.isArray(w)) return `liste[${w.length}]`;
  if (typeof w === 'object') return `objekt{${Object.keys(w).slice(0, 14).join(',')}}`;
  if (typeof w === 'boolean') return `wahrheitswert:${w}`;
  if (typeof w === 'number') return 'zahl';
  if (typeof w === 'string') {
    if (w === '') return 'text:leer';
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w)) return 'text:zeitpunkt';
    return `text(${w.length})`;
  }
  return typeof w;
}

const offen = /id$|_id|ref|booking|offer|order|trans|vat|ust|tax|steuer|mwst|rate|satz|net|gross|brutto|netto|amount|betrag|total|status|type|art|number|nummer|country|land|currency/i;

const felder = new Map();
let gelesen = 0;
let fehler = '';

for (const p of proben) {
  const a = await hole(`/invoice/${encodeURIComponent(p.invoice_id)}/data`, {});
  if (a.statusCode !== 200) {
    if (!fehler) fehler = `Status ${a.statusCode}`;
    continue;
  }
  const roh = a.body?.data;
  const r = Array.isArray(roh) ? roh[0] : roh;
  if (!r || typeof r !== 'object') continue;
  gelesen += 1;
  for (const [feld, wert] of Object.entries(r)) {
    if (!felder.has(feld)) felder.set(feld, { feld, arten: new Set(), werte: new Set() });
    const e = felder.get(feld);
    e.arten.add(art(wert));
    if (offen.test(feld) && (typeof wert !== 'object' || wert === null)) {
      const t = String(wert);
      if (t.length <= 40) e.werte.add(t);
    }
  }
}

const zeilen = [{
  json: {
    schritt: 'S24',
    bereich: 'Einzelrechnung',
    feld: '(Probe)',
    arten: `${gelesen} von ${proben.length} gelesen${fehler ? ', Fehler: ' + fehler : ''}`,
    beispielwerte: '',
    datenJson: JSON.stringify(saetze),
  },
}];

for (const e of [...felder.values()].sort((a, b) => a.feld.localeCompare(b.feld))) {
  zeilen.push({
    json: {
      schritt: 'S24',
      bereich: 'Einzelrechnung',
      feld: e.feld,
      arten: [...e.arten].slice(0, 4).join(' | '),
      beispielwerte: [...e.werte].slice(0, 6).join(' | '),
      datenJson: '',
    },
  });
}

return zeilen;

// Prueft, wie sich die Buchungsliste blaettern laesst.
// Nur Lesezugriffe. Ausgegeben werden Anzahlen, Feldnamen und Buchungs-IDs.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

// Holt die eigentlichen Buchungssaetze heraus, egal ob
// Array oder Objekt mit IDs als Schluesseln.
function saetze(antwort) {
  const roh = antwort?.data ?? antwort;
  if (Array.isArray(roh)) {
    return { form: 'array', liste: roh.map((e, i) => ({ schluessel: String(i), wert: e })) };
  }
  if (roh && typeof roh === 'object') {
    return {
      form: 'objekt mit IDs als Schluessel',
      liste: Object.entries(roh).map(([k, v]) => ({ schluessel: k, wert: v })),
    };
  }
  return { form: 'unbekannt', liste: [] };
}

function kennung(eintrag) {
  const w = eintrag.wert;
  if (w && typeof w === 'object') {
    return w.id ?? w.booking ?? eintrag.schluessel;
  }
  return eintrag.schluessel;
}

async function abruf(bezeichnung, query) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis,
      headers,
      qs: query,
      json: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    const { form, liste } = saetze(antwort.body);
    return {
      variante: bezeichnung,
      parameter: query,
      status: antwort.statusCode,
      form,
      anzahl: liste.length,
      erste_ids: liste.slice(0, 3).map(kennung),
      letzte_id: liste.length ? kennung(liste[liste.length - 1]) : null,
      huellenfelder:
        antwort.body && typeof antwort.body === 'object' && !Array.isArray(antwort.body)
          ? Object.keys(antwort.body)
          : [],
      eintragsfelder:
        liste.length && liste[0].wert && typeof liste[0].wert === 'object'
          ? Object.keys(liste[0].wert)
          : [],
    };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      parameter: query,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 300),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['ohne Parameter', {}],
  ['eckige Klammern Seite 1', { 'limit[start]': 0, 'limit[reply]': 10, 'order[time]': 'DESC' }],
  ['eckige Klammern Seite 2', { 'limit[start]': 10, 'limit[reply]': 10, 'order[time]': 'DESC' }],
  ['punktschreibweise Seite 1', { 'limit.start': 0, 'limit.reply': 10, 'order.time': 'DESC' }],
  ['flach Seite 1', { start: 0, reply: 10, order: 'DESC' }],
];

const ergebnisse = [];
for (const [bezeichnung, query] of varianten) {
  ergebnisse.push(await hole(bezeichnung, query));
}

const seite1 = ergebnisse.find((e) => e.variante === 'eckige Klammern Seite 1');
const seite2 = ergebnisse.find((e) => e.variante === 'eckige Klammern Seite 2');

let befund = 'unklar';
if (seite1?.anzahl && seite2?.anzahl) {
  const gleich = JSON.stringify(seite1.erste_ids) === JSON.stringify(seite2.erste_ids);
  befund = gleich ? 'Seite 1 und Seite 2 identisch - Blaettern wirkt NICHT' : 'Blaettern funktioniert';
}

// Eine Zeile je Variante, damit die Tabellenansicht alles zeigt.
const zeilen = ergebnisse.map((e) => ({
  json: {
    schritt: 'S5',
    variante: e.variante,
    status: e.status,
    form: e.form ?? '-',
    anzahl: e.anzahl ?? 0,
    huellenfelder: (e.huellenfelder ?? []).join(', ') || '-',
    eintragsfelder: (e.eintragsfelder ?? []).join(', ') || '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));

zeilen.push({
  json: {
    schritt: 'S5',
    variante: 'ZUSAMMENFASSUNG',
    status: '-',
    form: '-',
    anzahl: 0,
    huellenfelder: befund,
    eintragsfelder: '-',
    fehlermeldung: '-',
  },
});

return zeilen;

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token) throw new Error('Kein Token in der edoobox-Auth-Antwort enthalten.');
return [{ json: { token, edid } }];

const token = $('ZOO Token extrahieren').first().json.token;
const edid = $('ZOO Token extrahieren').first().json.edid;
const antwort = $input.first().json;
const anzahl = antwort && antwort.data ? Object.keys(antwort.data).length : 0;
const total = antwort && antwort.limit ? antwort.limit.total : anzahl;
return [{ json: { token, edid, anzahl, total } }];

// Teil 1: Wie heisst der Versatzparameter?  Seitengroesse fest auf 10.
// Teil 2: Wie gross darf eine Seite werden?
// Die Antwort spiegelt die verwendeten Werte im Feld limit zurueck.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const ids = liste.map(([k, v]) => (v && typeof v === 'object' ? v.id ?? k : k));
  const l = body?.limit ?? {};
  return {
    anzahl: liste.length,
    gemeldet_start: l.start ?? '-',
    gemeldet_reply: l.reply ?? '-',
    gemeldet_total: l.total ?? '-',
    erste_id: ids[0] ?? null,
  };
}

async function abruf(bezeichnung, qs) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis,
      headers,
      qs,
      json: true,
      returnFullResponse: true,
      timeout: 120000,
    });
    return { variante: bezeichnung, status: antwort.statusCode, ...auswerten(antwort.body) };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      anzahl: 0,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 160),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['A Vergleich limit 10', { limit: 10 }],
  ['B start', { limit: 10, start: 100 }],
  ['C skip', { limit: 10, skip: 100 }],
  ['D from', { limit: 10, from: 100 }],
  ['E begin', { limit: 10, begin: 100 }],
  ['F position', { limit: 10, position: 100 }],
  ['G index', { limit: 10, index: 100 }],
  ['H page', { limit: 10, page: 11 }],
  ['I first', { limit: 10, first: 100 }],
  ['J Seitenmass 500', { limit: 500 }],
  ['K Seitenmass 1000', { limit: 1000 }],
  ['L Seitenmass 5000', { limit: 5000 }],
];

const ergebnisse = [];
for (const [bezeichnung, qs] of varianten) {
  ergebnisse.push(await hole(bezeichnung, qs));
}

const vergleich = ergebnisse[0];

return ergebnisse.map((e) => ({
  json: {
    schritt: 'S8',
    variante: e.variante,
    status: e.status,
    anzahl: e.anzahl,
    gemeldet_start: e.gemeldet_start ?? '-',
    gemeldet_reply: e.gemeldet_reply ?? '-',
    gemeldet_total: e.gemeldet_total ?? '-',
    versatz_wirkt:
      e.erste_id && vergleich?.erste_id ? (e.erste_id !== vergleich.erste_id ? 'JA' : 'nein') : '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));

// Probiert moegliche Angebotsendpunkte durch und meldet je Versuch
// nur Statuscode, Anzahl der Eintraege und Feldnamen. Keine Klardaten.

const auth = $('S15 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const probe = $('S15 Angebotskennung holen').first().json;
const angebot = probe.eine_kennung;

if (!angebot) {
  throw new Error('Keine Angebotskennung in der Datenbank gefunden.');
}

const basis = 'https://app1.edoobox.com/v2';

const versuche = [
  { zweck: 'Angebotsliste', pfad: '/offer/list' },
  { zweck: 'Angebotsliste kurz', pfad: '/offer' },
  { zweck: 'Angebot einzeln', pfad: `/offer/${encodeURIComponent(angebot)}/data` },
  { zweck: 'Angebot einzeln kurz', pfad: `/offer/${encodeURIComponent(angebot)}` },
  { zweck: 'Angebotsgruppen', pfad: '/offerlist/list' },
  { zweck: 'Kategorien', pfad: '/category/list' },
  { zweck: 'Termine', pfad: '/date/list' },
  { zweck: 'Lektionen', pfad: '/lesson/list' },
  { zweck: 'Kurse', pfad: '/course/list' },
  { zweck: 'Preiskategorien', pfad: '/pricecategory/list' },
];

function feldnamen(o) {
  if (!o || typeof o !== 'object') return String(typeof o);
  return Object.keys(o).slice(0, 40).join(', ');
}

async function versuch(v) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis + v.pfad,
      headers,
      qs: { 'limit[start]': 0, 'limit[reply]': 3 },
      json: true,
      returnFullResponse: true,
      timeout: 45000,
      ignoreHttpStatusErrors: true,
    });

    const koerper = antwort.body ?? {};
    const inhalt = koerper.data;

    let anzahl = 0;
    let erstes = null;

    if (Array.isArray(inhalt)) {
      anzahl = inhalt.length;
      erstes = inhalt[0];
    } else if (inhalt && typeof inhalt === 'object') {
      const werte = Object.values(inhalt);
      anzahl = werte.length;
      erstes = werte[0];
    }

    return {
      schritt: 'S15',
      zweck: v.zweck,
      pfad: v.pfad.replace(/offer_[0-9a-f]+_[0-9]+/i, '{angebot}'),
      status: antwort.statusCode,
      gemeldet_total: koerper.limit?.total ?? null,
      eintraege: anzahl,
      huellenfelder: feldnamen(koerper),
      datenfelder: erstes && typeof erstes === 'object' ? feldnamen(erstes) : '',
    };
  } catch (e) {
    return {
      schritt: 'S15',
      zweck: v.zweck,
      pfad: v.pfad.replace(/offer_[0-9a-f]+_[0-9]+/i, '{angebot}'),
      status: e.statusCode ?? 'Fehler',
      gemeldet_total: null,
      eintraege: 0,
      huellenfelder: String(e.message ?? e).slice(0, 120),
      datenfelder: '',
    };
  }
}

const laufen = versuch.bind(this);
const zeilen = [];

for (const v of versuche) {
  zeilen.push(await laufen(v));
}

zeilen.push({
  schritt: 'S15',
  zweck: 'ZUSAMMENFASSUNG',
  pfad: '',
  status: '',
  gemeldet_total: probe.verschiedene_angebote,
  eintraege: probe.buchungen,
  huellenfelder: 'verschiedene Angebote laut Datenbank',
  datenfelder: '',
});

return zeilen.map((z) => ({ json: z }));

// Spiegelt alle Rechnungen samt Detailabruf. Ausgabe in Paketen,
// je Paket fuenf flache Listen: Kopf, Posten, Zeilen, Zahlungen, Belege.

const auth = $('S26 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abruf(pfad, qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2${pfad}`,
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abruf.bind(this);

function liste(h) {
  if (!h || typeof h !== 'object') return [];
  const d = h.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

function zahl(w) {
  if (w === null || w === undefined || w === '' || w === false || w === true) return null;
  const n = Number(String(w).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function zeitpunkt(w) {
  return typeof w === 'string' && /^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w) ? w : null;
}

function text(w, max) {
  if (w === null || w === undefined || typeof w === 'object') return null;
  const t = String(w);
  if (t === '' || t === 'false') return null;
  return max ? t.slice(0, max) : t;
}

function eintraege(w) {
  // Die Schnittstelle liefert Sammlungen entweder als Liste oder als Objekt.
  // Beides wird zu Paaren aus Schluessel und Wert vereinheitlicht.
  if (Array.isArray(w)) return w.map((v, i) => [String(i), v]);
  if (w && typeof w === 'object') return Object.entries(w);
  return [];
}

const statusText = { 1: 'offen', 2: 'bezahlt', 3: 'storniert' };

// 1. Rechnungsliste vollstaendig einlesen
const kopfroh = [];
let start = 0;
for (let i = 0; i < 20; i += 1) {
  const a = await hole('/invoice/list', { 'limit[start]': start, 'limit[reply]': 2000 });
  if (a.statusCode !== 200) throw new Error(`invoice/list Status ${a.statusCode}`);
  const d = liste(a.body);
  kopfroh.push(...d);
  if (d.length < 2000) break;
  start += 2000;
}

const kennungen = kopfroh.filter((r) => r && r.id).map((r) => String(r.id));
const ausListe = new Map(kopfroh.filter((r) => r && r.id).map((r) => [String(r.id), r]));

// 2. Detailabruf je Rechnung
async function detail(kennung) {
  const a = await hole(`/invoice/${encodeURIComponent(kennung)}/data`, {});
  if (a.statusCode !== 200) return { kennung, fehler: `Status ${a.statusCode}` };
  const r0 = a.body?.data;
  const r = Array.isArray(r0) ? r0[0] : r0;
  return { kennung, satz: r && typeof r === 'object' ? r : null };
}

const holeDetail = detail.bind(this);

const koepfe = [];
const posten = [];
const zeilen = [];
const zahlungen = [];
const belege = [];
const fehler = [];

function verarbeiten(kennung, r) {
  const l = ausListe.get(kennung) ?? {};
  const id = r?.invoice_data && typeof r.invoice_data === 'object' ? r.invoice_data : {};
  const c = id.counts && typeof id.counts === 'object' ? id.counts : {};
  const adr = id.address && typeof id.address === 'object' ? id.address : {};
  const st = zahl(l.status ?? r?.status);

  koepfe.push({
    invoice_id: kennung,
    invoice_number: text(l.number ?? r?.number ?? id.number, 40),
    user_ref_roh: text(l.user ?? r?.user, 60),
    status: st,
    status_text: statusText[st] ?? null,
    currency: (text(l.currency ?? id.currency, 3) ?? 'EUR').toUpperCase(),
    amount: zahl(l.amount ?? r?.amount),
    amount_pay: zahl(r?.amount_pay),
    line_total: zahl(c.lineTotalAmount),
    tax_basis_total: zahl(c.taxBasisTotalAmount),
    tax_total: zahl(c.taxTotalAmount),
    grand_total: zahl(c.grandTotalAmount),
    due_payable: zahl(c.duePayableAmount),
    prepaid_total: zahl(c.totalPrepaidAmount),
    allowance_total: zahl(c.allowanceTotalAmount),
    charge_total: zahl(c.chargeTotalAmount),
    date_create: zeitpunkt(l.date_create ?? r?.date_create),
    date_pay: zeitpunkt(l.date_pay ?? r?.date_pay),
    date_payuntil: zeitpunkt(l.date_payuntil ?? r?.date_payuntil),
    date_cancelled: zeitpunkt(l.date_cancelled ?? r?.date_cancelled),
    offer_start_date: zeitpunkt(l.offer_start_date ?? r?.offer_start_date),
    address_country: text(adr.country, 8),
    address_postcode: text(adr.postcode, 16),
    buyer_reference: text(adr.buyer_reference, 80),
    language: text(id.language, 8),
  });

  // Posten aus items.contained
  const enthalten = r?.items && typeof r.items === 'object' ? r.items.contained : null;
  for (const [schluessel, w] of eintraege(enthalten)) {
    if (!w || typeof w !== 'object') continue;
    const k = String(w.id ?? schluessel);
    const pro = w.promotion && typeof w.promotion === 'object' && !Array.isArray(w.promotion) ? w.promotion : {};
    posten.push({
      invoice_id: kennung,
      item_key: k,
      item_type: text(w.type, 40),
      transaction_id: text(w.transaction, 60),
      transaction_number: text(w.number, 40),
      description: text(w.description, 300),
      amount: zahl(w.amount),
      vat_percent: zahl(w.vat_percent),
      vat_ref: text(w.vat, 60),
      promotion_name: text(pro.name, 120),
      promotion_amount: zahl(pro.amount),
      promotion_vat_percent: zahl(pro.vat_percent),
      pricecategory_count: Array.isArray(w.pricecategory)
        ? w.pricecategory.length
        : (w.pricecategory && typeof w.pricecategory === 'object' ? Object.keys(w.pricecategory).length : null),
    });
  }

  // Gedruckte Zeilen aus invoice_data.items
  const gedruckt = Array.isArray(id.items) ? id.items : (id.items && typeof id.items === 'object' ? Object.values(id.items) : []);
  let laufend = 0;
  for (const z of gedruckt) {
    if (!z || typeof z !== 'object') continue;
    laufend += 1;
    const preis = z.price && typeof z.price === 'object' ? z.price : {};
    const mwst = z.vat && typeof z.vat === 'object' ? z.vat : {};
    zeilen.push({
      invoice_id: kennung,
      position: zahl(z.position) ?? laufend,
      quantity: zahl(z.quantity),
      price_net: zahl(preis.net),
      price_net_summation: zahl(preis.net_summation),
      vat_type: text(mwst.type, 40),
      vat_percent: zahl(mwst.percent),
      transaction_number: text(z.transaction_number, 40),
      details: text(z.details, 400),
    });
  }

  // Zahlungen
  for (const [schluessel, w] of eintraege(r?.pay)) {
    if (!w || typeof w !== 'object') continue;
    const pid = text(w.id, 60) ?? String(schluessel);
    if (!pid) continue;
    zahlungen.push({
      pay_id: pid,
      invoice_id: kennung,
      amount: zahl(w.amount),
      currency: (text(w.currency, 3) ?? 'EUR').toUpperCase(),
      status: zahl(w.status),
      date_pay: zeitpunkt(w.date_pay),
      system: text(w.system, 40),
      system_id: text(w.system_id, 40),
    });
  }

  // Belege
  for (const [schluessel, w] of eintraege(r?.receipt)) {
    if (!w || typeof w !== 'object') continue;
    const rid = text(w.id, 60) ?? String(schluessel);
    if (!rid) continue;
    belege.push({
      receipt_id: rid,
      invoice_id: kennung,
      receipt_number: text(w.number, 40),
      amount: zahl(w.amount),
      currency: (text(w.currency, 3) ?? 'EUR').toUpperCase(),
      date_create: zeitpunkt(w.date_create),
    });
  }
}

const gleichzeitig = 8;
for (let i = 0; i < kennungen.length; i += gleichzeitig) {
  const gruppe = kennungen.slice(i, i + gleichzeitig);
  const ergebnisse = await Promise.all(gruppe.map((k) => holeDetail(k)));
  for (const e of ergebnisse) {
    if (e.fehler) { fehler.push(`${e.kennung}: ${e.fehler}`); continue; }
    if (!e.satz) { fehler.push(`${e.kennung}: leere Antwort`); continue; }
    verarbeiten(e.kennung, e.satz);
  }
}

// 3. In Pakete zerlegen. Kinder folgen ihrem Kopf.
const paketgroesse = 300;
const pakete = [];

for (let i = 0; i < koepfe.length; i += paketgroesse) {
  const kopfpaket = koepfe.slice(i, i + paketgroesse);
  const menge = new Set(kopfpaket.map((k) => k.invoice_id));
  pakete.push({
    json: {
      schritt: 'S26',
      paket: pakete.length + 1,
      koepfe: kopfpaket.length,
      fehlerhaft_gesamt: fehler.length,
      fehlerliste: fehler.slice(0, 10),
      kopfJson: JSON.stringify(kopfpaket),
      postenJson: JSON.stringify(posten.filter((p) => menge.has(p.invoice_id))),
      zeilenJson: JSON.stringify(zeilen.filter((z) => menge.has(z.invoice_id))),
      zahlungJson: JSON.stringify(zahlungen.filter((z) => menge.has(z.invoice_id))),
      belegJson: JSON.stringify(belege.filter((b) => menge.has(b.invoice_id))),
    },
  });
}

return pakete;

// P05 - Eingaben des manuellen Wiederanlaufs.
// Vor dem Ausfuehren hier die gewuenschten Werte setzen:
//   Ressource   = 'alle' oder eine der zwoelf festen Kennungen
//   Abgleichsart= 'normal' (ohne Loeschabgleich) oder 'voll' (mit Loeschabgleich)
//   Hinweis     = optionaler Anlass (wird im sync_run-Protokoll gespeichert)
// Feste Auswahlliste wird im Knoten 'P05 Plan aufloesen' erzwungen;
// freie Tabellen-/SQL-Namen sind damit ausgeschlossen (E-31c, E-31j).

return [{
  json: {
    Ressource: 'alle',
    Abgleichsart: 'normal',
    Hinweis: '',
  },
}];

// P05 - Plan aufloesen
// Validiert 'Ressource' gegen die feste Liste und erzeugt je ausgewaehlter
// Ressource ein Eingangselement fuer den P90-Aufruf (Modus 'Run once for each item').

const eingabe = $('P05 Eingaben').first().json;
const runId = $('P05 Lauf anlegen').first().json.run_id;

const KONFIG = {
  edo_admins:         { api_path: '/admin/list',        target_table: 'trainer_admin',    primary_key: 'admin_id',         page_size: 2000 },
  edo_vat:            { api_path: '/vat/list',          target_table: 'vat',              primary_key: 'vat_id',           page_size: 2000 },
  edo_countries:      { api_path: '/country/list',      target_table: 'country',          primary_key: 'country_id',       page_size: 2000 },
  edo_categories:     { api_path: '/category/list',     target_table: 'category',         primary_key: 'category_id',      page_size: 2000 },
  edo_offers:         { api_path: '/offer/list',        target_table: 'offer',            primary_key: 'offer_id',         page_size: 2000 },
  edo_users:          { api_path: '/user/list',         target_table: 'user_account',     primary_key: 'user_ref',         page_size: 2000 },
  edo_dates:          { api_path: '/date/list',         target_table: 'offer_date',       primary_key: 'date_id',          page_size: 2000 },
  edo_bookings:       { api_path: '/booking/list',      target_table: 'booking',          primary_key: 'booking_id',       page_size: 2000 },
  edo_pricecategories:{ api_path: '/pricecategory/list', target_table: 'pricecategory',    primary_key: 'pricecategory_id',  page_size: 2000 },
  edo_attendances:    { api_path: '/attendance/list',   target_table: 'attendance',       primary_key: 'attendance_id',    page_size: 2000 },
  edo_invoices:       { api_path: '/invoice/list',      target_table: 'invoice',          primary_key: 'invoice_id',       page_size: 2000 },
  edo_transactions:   { api_path: '/transaction/list',  target_table: 'transaction_full', primary_key: 'transaction_id',   page_size: 2000 },
};

const ressourcenWahl = String(eingabe.Ressource == null ? 'alle' : eingabe.Ressource).trim();
const abgleichsart = String(eingabe.Abgleichsart == null ? 'normal' : eingabe.Abgleichsart).trim();

if (abgleichsart !== 'normal' && abgleichsart !== 'voll') {
  throw new Error('P05: Ungueltige Abgleichsart "' + abgleichsart + '". Zulaessig: normal, voll.');
}
const trackDeletions = abgleichsart === 'voll';

let auswahl;
if (ressourcenWahl === 'alle') {
  auswahl = Object.keys(KONFIG);
} else {
  if (!KONFIG[ressourcenWahl]) {
    throw new Error('P05: Unbekannte Ressource "' + ressourcenWahl + '". Zulaessig: alle, ' + Object.keys(KONFIG).join(', '));
  }
  auswahl = [ressourcenWahl];
}

return auswahl.map(function (k) {
  return {
    json: {
      resource_key: k,
      api_path: KONFIG[k].api_path,
      target_table: KONFIG[k].target_table,
      primary_key: KONFIG[k].primary_key,
      page_size: KONFIG[k].page_size,
      run_id: runId,
      track_deletions: trackDeletions,
    },
  };
});

// P05 - Ergebnis aggregieren
// Wertet die von P90 in sync_run_resource hinterlegten Zaehlwerte aus und
// vergleicht sie mit der geplanten Auswahl (E-31g).

const plan = $('P05 Plan aufloesen').all();
const zeilen = $('P05 Ressourcen lesen').all();
const erwartet = plan.map(function (p) { return p.json.resource_key; });

function z(w) { const n = Number(w); return Number.isFinite(n) ? n : 0; }

const gelesen = {};
for (const row of zeilen) { gelesen[row.json.resource] = row.json; }

let seen = 0, neu = 0, geaendert = 0, geloescht = 0, api = 0;
const fehlend = [];
const unvollstaendig = [];

for (const r of erwartet) {
  const row = gelesen[r];
  if (!row) { fehlend.push(r); continue; }
  seen += z(row.gelesen);
  neu += z(row.neu);
  geaendert += z(row.geaendert);
  geloescht += z(row.geloescht);
  api += z(row.api_calls);
  if (row.gemeldet === null || row.gemeldet === undefined || z(row.gemeldet) !== z(row.gelesen)) {
    unvollstaendig.push(r);
  }
}

const resourcesFailed = fehlend.length + unvollstaendig.length;
const status = resourcesFailed === 0 ? 'erfolgreich' : 'fehler';

return [{
  json: {
    run_id: $('P05 Lauf anlegen').first().json.run_id,
    status,
    resources_total: erwartet.length,
    resources_failed: resourcesFailed,
    records_seen: seen,
    records_new: neu,
    records_changed: geaendert,
    records_deleted: geloescht,
    api_calls_total: api,
    error_text: resourcesFailed === 0
      ? null
      : ('Fehlend: ' + (fehlend.join(',') || '-') + '; unvollstaendig: ' + (unvollstaendig.join(',') || '-')),
  },
}];

// Untersucht ausschliesslich Datumszeilen mit mehreren leader-Eintraegen.
// Aus Administratoren werden nur ID, Vorname, Nachname und Kurzzeichen genutzt.
// Kontakt-, Adress- und Teilnehmerdaten werden nicht ausgegeben.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt.');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const basis = 'https://app1.edoobox.com/v2';

function rowsAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

async function holeAlle(pfad) {
  const alle = [];
  const reply = 2000;
  let start = 0;
  let total = null;
  for (let seite = 1; seite <= 20; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET',
      url: basis + pfad,
      headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true,
      returnFullResponse: true,
      timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
    if (!(a.statusCode >= 200 && a.statusCode < 300)) {
      throw new Error(`${pfad}: HTTP ${a.statusCode}`);
    }
    const rows = rowsAus(a.body);
    if (total === null && a.body?.limit?.total !== undefined) total = Number(a.body.limit.total);
    alle.push(...rows);
    start += rows.length;
    if (rows.length === 0 || rows.length < reply || (total !== null && start >= total)) break;
  }
  if (total !== null && alle.length !== total) {
    throw new Error(`${pfad}: unvollstaendig, gemeldet ${total}, gelesen ${alle.length}`);
  }
  return alle;
}

const admins = await holeAlle.call(this, '/admin/list');
const offers = await holeAlle.call(this, '/offer/list');
const dates = await holeAlle.call(this, '/date/list');

const adminNachId = new Map(admins.map(a => [String(a.id), a]));
const offerNachId = new Map(offers.map(o => [String(o.id), o]));
const mehrfach = dates.filter(d => Array.isArray(d.leader) && d.leader.length > 1);

function trainerText(id) {
  const a = adminNachId.get(String(id));
  if (!a) return `${id} (historisch oder nicht mehr vorhanden)`;
  const name = [a.first_name, a.last_name].filter(Boolean).join(' ').trim();
  const kuerzel = a.shortcut ? ` [${a.shortcut}]` : '';
  return `${name || '(ohne Namen)'}${kuerzel} (${id})`;
}

const ausgabe = mehrfach
  .sort((a, b) => String(a.date_start).localeCompare(String(b.date_start)))
  .map(d => {
    const roh = d.leader.map(String);
    const eindeutig = [...new Set(roh)];
    const o = offerNachId.get(String(d.offer));
    return {
      json: {
        schritt: 'S53',
        datum_id: d.id,
        beginn: d.date_start,
        ende: d.date_end,
        angebot_id: d.offer,
        kursnummer: o?.number ?? '-',
        angebot: o?.name ?? '(Angebot nicht gefunden)',
        leader_eintraege: roh.length,
        verschiedene_trainer: eindeutig.length,
        trainer: eindeutig.map(trainerText).join(' / '),
        bewertung: eindeutig.length === 1
          ? 'Doppelte identische Trainerkennung'
          : 'Mehrere unterschiedliche Trainer',
      },
    };
  });

const verschiedeneAngebote = new Set(mehrfach.map(d => String(d.offer))).size;
const echteMehrfach = ausgabe.filter(x => x.json.verschiedene_trainer > 1).length;
const doppelte = ausgabe.filter(x => x.json.verschiedene_trainer === 1).length;

ausgabe.push({
  json: {
    schritt: 'S53 KONTROLLE',
    datum_id: '-',
    beginn: '-',
    ende: '-',
    angebot_id: '-',
    kursnummer: '-',
    angebot: `${mehrfach.length} Datumszeilen in ${verschiedeneAngebote} Angeboten`,
    leader_eintraege: mehrfach.reduce((s, d) => s + d.leader.length, 0),
    verschiedene_trainer: null,
    trainer: '-',
    bewertung: `${echteMehrfach} echte Mehrfachzuordnungen / ${doppelte} doppelte identische Kennungen`,
  },
});

return ausgabe;

// Erkundet /v2/invoice/list: Statuscode, Satzzahl, Huellenfelder und
// Feldbestand je Rechnung. Zeigt Klarwerte nur bei steuerlich
// bedeutsamen Feldern, sonst nur Werttypen.

const auth = $('S22 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function abrufen(qs) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://app1.edoobox.com/v2/invoice/list',
    headers,
    qs,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = abrufen.bind(this);

// Erste Seite als Probe. 500 Saetze genuegen fuer den Feldbestand.
const erste = await hole({ 'limit[start]': 0, 'limit[reply]': 500 });

const zeilen = [];

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'statuscode',
    arten: String(erste.statusCode),
    beispielwerte: '',
  },
});

if (erste.statusCode !== 200) {
  zeilen.push({
    json: {
      schritt: 'S22',
      bereich: 'Antwort',
      feld: 'fehlertext',
      arten: String(erste.body && typeof erste.body === 'object'
        ? JSON.stringify(erste.body).slice(0, 300)
        : String(erste.body).slice(0, 300)),
      beispielwerte: '',
    },
  });
  return zeilen;
}

const huelle = erste.body && typeof erste.body === 'object' ? erste.body : {};

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'huellenfelder',
    arten: Object.keys(huelle).join(', '),
    beispielwerte: '',
  },
});

// Satzzahl aus allen plausiblen Stellen einsammeln.
for (const kandidat of ['total', 'count', 'amount', 'records', 'result', 'meta']) {
  if (huelle[kandidat] !== undefined && typeof huelle[kandidat] !== 'object') {
    zeilen.push({
      json: {
        schritt: 'S22',
        bereich: 'Antwort',
        feld: `huelle.${kandidat}`,
        arten: String(huelle[kandidat]),
        beispielwerte: '',
      },
    });
  }
}

const daten = Array.isArray(huelle.data)
  ? huelle.data
  : huelle.data && typeof huelle.data === 'object'
    ? Object.values(huelle.data)
    : [];

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'saetze auf erster seite',
    arten: String(daten.length),
    beispielwerte: '',
  },
});

function art(wert) {
  if (wert === null) return 'null';
  if (Array.isArray(wert)) return `liste[${wert.length}]`;
  if (typeof wert === 'object') return `objekt{${Object.keys(wert).slice(0, 12).join(',')}}`;
  if (typeof wert === 'boolean') return `wahrheitswert:${wert}`;
  if (typeof wert === 'number') return 'zahl';
  if (typeof wert === 'string') {
    if (wert === '') return 'text:leer';
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(wert)) return 'text:zeitpunkt';
    if (/^-?[0-9]+([.,][0-9]+)?$/.test(wert)) return 'text:zahl';
    return `text(${wert.length})`;
  }
  return typeof wert;
}

// Bei diesen Feldnamen sind Klarwerte unbedenklich und aufschlussreich.
const offen = /vat|ust|tax|steuer|mwst|currency|waehrung|status|type|art|country|land|state|paid|open|number|nummer|amount|betrag|total|net|gross|brutto|netto|date|datum|time|rate|satz|b2b|booking|offer|reverse|charge/i;

const uebersicht = new Map();

for (const r of daten) {
  if (!r || typeof r !== 'object') continue;
  for (const [feld, wert] of Object.entries(r)) {
    if (!uebersicht.has(feld)) uebersicht.set(feld, { feld, arten: new Set(), werte: new Set(), gefuellt: 0 });
    const e = uebersicht.get(feld);
    e.arten.add(art(wert));
    if (wert !== null && wert !== '' && wert !== false) e.gefuellt += 1;
    if (offen.test(feld) && (typeof wert !== 'object' || wert === null)) {
      const t = String(wert);
      if (t.length <= 28) e.werte.add(t);
    }
  }
}

for (const e of [...uebersicht.values()].sort((a, b) => a.feld.localeCompare(b.feld))) {
  zeilen.push({
    json: {
      schritt: 'S22',
      bereich: 'Rechnung',
      feld: e.feld,
      arten: `${[...e.arten].slice(0, 4).join(' | ')}  (gefuellt ${e.gefuellt}/${daten.length})`,
      beispielwerte: [...e.werte].slice(0, 8).join(' | '),
    },
  });
}

// Gesamtzahl durch Blaettern bestimmen, falls die Huelle sie nicht nennt.
let gesamt = daten.length;
let abrufe = 1;

if (daten.length === 500) {
  let start = 500;
  while (abrufe < 30) {
    const w = await hole({ 'limit[start]': start, 'limit[reply]': 2000 });
    abrufe += 1;
    if (w.statusCode !== 200) break;
    const h = w.body && typeof w.body === 'object' ? w.body : {};
    const d = Array.isArray(h.data) ? h.data : h.data && typeof h.data === 'object' ? Object.values(h.data) : [];
    gesamt += d.length;
    if (d.length < 2000) break;
    start += 2000;
  }
}

zeilen.push({
  json: {
    schritt: 'S22',
    bereich: 'Antwort',
    feld: 'rechnungen gesamt',
    arten: `${gesamt} bei ${abrufe} Abrufen`,
    beispielwerte: '',
  },
});

return zeilen;

// Vollstaendige, rein lesende Strukturinventur der zwoelf im
// edoobox-Schaubild genannten Ressourcen. Es werden niemals Feldwerte,
// Namen, E-Mail-Adressen oder andere Personenangaben ausgegeben.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2';
const ressourcen = [
  { name: 'edo_admins',          pfade: ['/admin/list', '/admins/list', '/administrator/list'] },
  { name: 'Vat',                 pfade: ['/vat/list', '/vats/list'] },
  { name: 'Countries',           pfade: ['/country/list', '/countries/list'] },
  { name: 'edo_categories',      pfade: ['/category/list', '/categories/list'] },
  { name: 'edo_offers',          pfade: ['/offer/list', '/offers/list'] },
  { name: 'edo_users',           pfade: ['/user/list', '/users/list'] },
  { name: 'edo_dates',           pfade: ['/date/list', '/dates/list', '/module/list', '/modules/list'] },
  { name: 'edo_bookings',        pfade: ['/booking/list', '/bookings/list'] },
  { name: 'edo_pricecategories', pfade: ['/pricecategory/list', '/pricecategories/list'] },
  { name: 'edo_attendances',     pfade: ['/attendance/list', '/attendances/list'] },
  { name: 'edo_invoices',        pfade: ['/invoice/list', '/invoices/list'] },
  { name: 'edo_transactions',    pfade: ['/transaction/list', '/transactions/list'] },
];

const relation = /(^|\.)(offer|offers|user|users|admin|admins|participant|participants|date|dates|booking|bookings|invoice|invoices|transaction|transactions|pay|paytrans|country|category|vat|number|permission)(\[\])?$/i;

function typ(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function siehtWieIdAus(k) {
  return /^(booking|offer|user|admin|date|invoice|transaction|attendance|category|pricecategory)_[a-z0-9]+(?:_[a-z0-9-]+)?$/i.test(k)
    || /^[a-f0-9]{16,}$/i.test(k)
    || /^\d{7,}$/.test(k);
}

function datenAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

function wertSignatur(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'object') return null;
  return `${typeof v}:${String(v)}`;
}

function erfasse(stats, relationswerte, v, pfad) {
  if (!pfad) return;
  const s = stats.get(pfad) ?? { typen: new Set(), vorkommen: 0, gefuellt: 0 };
  s.typen.add(typ(v));
  s.vorkommen += 1;
  if (v !== null && v !== undefined && v !== '') s.gefuellt += 1;
  stats.set(pfad, s);

  if (relation.test(pfad)) {
    const sig = wertSignatur(v);
    if (sig !== null) {
      const r = relationswerte.get(pfad) ?? { gefuellt: 0, verschieden: new Set() };
      r.gefuellt += 1;
      r.verschieden.add(sig);
      relationswerte.set(pfad, r);
    }
  }

  if (Array.isArray(v)) {
    for (const x of v) erfasse(stats, relationswerte, x, pfad + '[]');
    return;
  }

  if (v && typeof v === 'object') {
    const keys = Object.keys(v);
    const idMap = keys.length > 0 && keys.filter(siehtWieIdAus).length / keys.length >= 0.8;
    if (idMap) {
      for (const x of Object.values(v)) erfasse(stats, relationswerte, x, pfad + '.*');
    } else {
      for (const [k, x] of Object.entries(v)) erfasse(stats, relationswerte, x, pfad + '.' + k);
    }
  }
}

async function abruf(pfad, start, reply) {
  try {
    return await this.helpers.httpRequest({
      method: 'GET',
      url: basis + pfad,
      headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true,
      returnFullResponse: true,
      timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
  } catch (e) {
    return {
      statusCode: e?.response?.status ?? e?.httpCode ?? 'Fehler',
      body: { _fehler: String(e?.message ?? e).slice(0, 160) },
    };
  }
}

const ausgabe = [];

for (const ressource of ressourcen) {
  const versuche = [];
  let treffer = null;

  for (const pfad of ressource.pfade) {
    const probe = await abruf.call(this, pfad, 0, 3);
    const status = probe.statusCode ?? 'Fehler';
    const zeilen = status >= 200 && status < 300 ? datenAus(probe.body).length : 0;
    versuche.push(`${pfad}=${status}/${zeilen}`);
    if (!treffer && status >= 200 && status < 300 && probe.body && Object.prototype.hasOwnProperty.call(probe.body, 'data')) {
      treffer = pfad;
    }
  }

  if (!treffer) {
    ausgabe.push({
      json: {
        schritt: 'S51',
        bereich: 'A Ressource',
        ressource: ressource.name,
        endpoint: '-',
        datensaetze: 0,
        feldpfade: 0,
        hinweis: 'Kein verwendbarer Endpunkt / ' + versuche.join(' ; '),
      },
    });
    continue;
  }

  const stats = new Map();
  const relationswerte = new Map();
  const reply = 2000;
  let start = 0;
  let gesamt = 0;
  let gemeldet = null;
  let seiten = 0;
  let abbruch = 'vollstaendig';
  let vorigeSignatur = null;

  while (seiten < 50) {
    const antwort = await abruf.call(this, treffer, start, reply);
    const status = antwort.statusCode ?? 'Fehler';
    if (!(status >= 200 && status < 300)) {
      abbruch = `Fehler ${status} ab Offset ${start}`;
      break;
    }

    const body = antwort.body ?? {};
    const rows = datenAus(body);
    if (gemeldet === null && body.limit?.total !== undefined) gemeldet = Number(body.limit.total);
    seiten += 1;

    const ids = rows.slice(0, 2).concat(rows.slice(-2)).map((r) => {
      if (!r || typeof r !== 'object') return typ(r);
      return r.id ?? r.number ?? Object.keys(r).sort().join(',');
    });
    const signatur = JSON.stringify(ids);
    if (seiten > 1 && signatur === vorigeSignatur && rows.length > 0) {
      abbruch = 'Pagination vom Endpunkt ignoriert; Wiederholung erkannt';
      break;
    }
    vorigeSignatur = signatur;

    for (const row of rows) {
      if (!row || typeof row !== 'object') continue;
      for (const [k, v] of Object.entries(row)) erfasse(stats, relationswerte, v, k);
    }

    gesamt += rows.length;
    start += rows.length;
    if (rows.length === 0) break;
    if (gemeldet !== null && start >= gemeldet) break;
    if (rows.length < reply) break;
  }

  if (seiten >= 50) abbruch = 'Sicherheitsgrenze von 50 Seiten erreicht';

  const feldbericht = [...stats.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([pfad, s]) => `${pfad}{${[...s.typen].sort().join('+')};${s.gefuellt}/${s.vorkommen}}`)
    .join(' | ');

  const relationsbericht = [...relationswerte.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([pfad, r]) => `${pfad}{gefüllt:${r.gefuellt};verschieden:${r.verschieden.size}}`)
    .join(' | ');

  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'A Ressource',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: stats.size,
      hinweis: `gemeldet ${gemeldet ?? '-'} / Seiten ${seiten} / ${abbruch} / Versuche ${versuche.join(' ; ')}`,
    },
  });
  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'B Feldinventar',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: stats.size,
      hinweis: feldbericht || '-',
    },
  });
  ausgabe.push({
    json: {
      schritt: 'S51',
      bereich: 'C Beziehungen',
      ressource: ressource.name,
      endpoint: treffer,
      datensaetze: gesamt,
      feldpfade: relationswerte.size,
      hinweis: relationsbericht || 'keine technischen Beziehungsfelder erkannt',
    },
  });
}

return ausgabe;

// Zwei Fragen in einem Lauf:
//  Gruppe 1  weitere Namen fuer den Versatz
//  Gruppe 2  Schreibweise des Filters auf Angebot beziehungsweise Buchung
// Erkennungszeichen: sinkt gemeldet_total unter 4038, wurde der Filter angenommen.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const eintraege = liste.map(([k, v]) => (v && typeof v === 'object' ? v : { id: k }));
  const l = body?.limit ?? {};
  return {
    anzahl: liste.length,
    gemeldet_start: l.start ?? '-',
    gemeldet_reply: l.reply ?? '-',
    gemeldet_total: l.total ?? '-',
    erste_id: eintraege[0]?.id ?? null,
    erstes_angebot: eintraege[0]?.offer ?? null,
  };
}

async function abruf(bezeichnung, qs) {
  try {
