-- P90a: ergaenzt last_run_id in den bereits bestehenden Rohdatentabellen (Voraussetzung
-- fuer den Loeschabgleich in P90) und legt die noch fehlenden neun Rohdatentabellen an.
-- Struktur der neuen Tabellen bewusst generisch (Primaerschluessel + payload jsonb +
-- Meta-Spalten), damit P90 sie ohne Sonderfaelle bedienen kann. Zusaetzliche typisierte
-- Spalten koennen spaeter bei Bedarf per ALTER TABLE ergaenzt werden (wie bei offer/S16a).

ALTER TABLE edoobox_raw.sync_run ADD COLUMN IF NOT EXISTS resources_total  integer;
ALTER TABLE edoobox_raw.sync_run ADD COLUMN IF NOT EXISTS resources_failed integer;
