if (!stundenDaten) {
  const letzteStunde = aktuelleStunde === 0 ? 23 : aktuelleStunde - 1;
  stundenDaten = response.days[0].hours.find(h => {
    return parseInt(h.datetime.split(':')[0]) === letzteStunde;
  });
}

if (!stundenDaten) {
