// P04 - Ergebnis auswerten
// Liest die Einzelwerte der Kontrollabfrage und stellt Status + Bericht zusammen.
// Harte Fehler (Laufalter, offene Kosten, harte Beziehungsbrueche) setzen den
// Lauf auf 'fehler'. Warnungen werden nur gemeldet.

const r = $('P04 Kontrollen ausfuehren').first().json;

function zahl(w) {
  const n = Number(w);
  return Number.isFinite(n) ? n : 0;
}

const imBetriebsfenster = (r.wochentag >= 1 && r.wochentag <= 5 && r.stunde >= 8 && r.stunde <= 23);
const p01Alter = (r.p01_alter_sek === null || r.p01_alter_sek === undefined) ? null : zahl(r.p01_alter_sek);
const p02Alter = (r.p02_alter_sek === null || r.p02_alter_sek === undefined) ? null : zahl(r.p02_alter_sek);
const p03Alter = (r.p03_alter_sek === null || r.p03_alter_sek === undefined) ? null : zahl(r.p03_alter_sek);

const fehler = [];
const warnungen = [];
const info = [];

// P01 nur im Betriebszeitfenster pruefen (werktags 08:00-23:45).
if (imBetriebsfenster && (p01Alter === null || p01Alter > 1800)) {
  fehler.push(p01Alter === null
    ? 'P01: kein erfolgreicher Lauf vorhanden'
    : 'P01: letzter erfolgreicher Lauf vor ' + Math.round(p01Alter / 60) + ' Minuten');
}

if (p02Alter === null || p02Alter > 93600) {
  fehler.push(p02Alter === null
    ? 'P02: kein erfolgreicher Lauf vorhanden'
    : 'P02: letzter erfolgreicher Lauf vor ' + (p02Alter / 3600).toFixed(1) + ' Stunden');
}

if (p03Alter === null || p03Alter > 691200) {
  fehler.push(p03Alter === null
    ? 'P03: kein erfolgreicher Vollabgleich vorhanden'
    : 'P03: letzter Vollabgleich vor ' + (p03Alter / 86400).toFixed(1) + ' Tagen');
}

if (zahl(r.offen_kosten) > 0)            fehler.push('Offene Kostenkonfigurationen: ' + r.offen_kosten);
if (zahl(r.date_ohne_offer) > 0)         fehler.push('Termine ohne Angebot: ' + r.date_ohne_offer);
if (zahl(r.position_ohne_buchung) > 0)   fehler.push('Buchungspositionen ohne Buchung: ' + r.position_ohne_buchung);
if (zahl(r.trans_ohne_buchung) > 0)      fehler.push('Buchungstransaktionen ohne Buchung: ' + r.trans_ohne_buchung);

if (zahl(r.buchung_ohne_offer) > 0)      warnungen.push('Buchungen ohne Angebot: ' + r.buchung_ohne_offer);
if (zahl(r.leader_ohne_trainer) > 0)     warnungen.push('Trainerzuordnungen ohne Trainerprofil (historisch): ' + r.leader_ohne_trainer);
if (zahl(r.attendance_ohne_termin) > 0)  warnungen.push('Anwesenheiten ohne Termin: ' + r.attendance_ohne_termin);
if (zahl(r.angebote_ohne_trainer) > 0)   warnungen.push('Produktive Angebote ohne Trainer: ' + r.angebote_ohne_trainer);

info.push(
  'DB-I (ab 2023): Netto ' + r.netto +
  ', Trainer ' + r.trainerkosten +
  ', Plattform ' + r.plattformkosten +
  ', direkte Kosten ' + r.direkte_kosten +
  ', DB I ' + r.db1 +
  ', berechenbare Angebote ' + r.berechenbare_angebote
);

const status = fehler.length ? 'fehler' : 'erfolgreich';
const bericht = ['P04-Kontrolle']
  .concat(fehler.map(function (f) { return 'FEHLER: ' + f; }))
  .concat(warnungen.map(function (w) { return 'WARNUNG: ' + w; }))
  .concat(info.map(function (i) { return 'INFO: ' + i; }))
  .join(' | ');

return [{
  json: {
    run_id: $('P04 Lauf anlegen').first().json.run_id,
    status,
    fehler: fehler.length,
    warnungen: warnungen.length,
    bericht,
    error_text: (fehler.length || warnungen.length) ? bericht.slice(0, 4000) : null,
  },
}];

