parameters.jsCode:
// P04 - Ergebnis auswerten
// Liest die Einzelwerte der Kontrollabfrage und stellt Status + Bericht zusammen.
// Harte Fehler (Laufalter, offene Kosten, harte Beziehungsbrueche) setzen den
// Lauf auf 'fehler'. Warnungen werden nur gemeldet.

const r = $('P04 Kontrollen ausfuehren').first().json;

function zahl(w) {
  const n = Number(w);
  return Number.isFinite(n) ? n : 0;
}

const imBetriebsfenster = (r.wochentag >= 1 && r.wochentag <= 5 && r.stunde >= 8 && r.stunde <= 23);
const p01Alter = (r.p01_alter_sek === null || r.p01_alter_sek === undefined) ? null : zahl(r.p01_alter_sek);
const p02Alter = (r.p02_alter_sek === null || r.p02_alter_sek === undefined) ? null : zahl(r.p02_alter_sek);
const p03Alter = (r.p03_alter_sek === null || r.p03_alter_sek === undefined) ? null : zahl(r.p03_alter_sek);

const fehler = [];
const warnungen = [];
const info = [];

// P01 nur im Betriebszeitfenster pruefen (werktags 08:00-23:45).
if (imBetriebsfenster && (p01Alter === null || p01Alter > 1800)) {
  fehler.push(p01Alter === null
    ? 'P01: kein erfolgreicher Lauf vorhanden'
    : 'P01: letzter erfolgreicher Lauf vor ' + Math.round(p01Alter / 60) + ' Minuten');
}

if (p02Alter === null || p02Alter > 93600) {
  fehler.push(p02Alter === null
    ? 'P02: kein erfolgreicher Lauf vorhanden'
    : 'P02: letzter erfolgreicher Lauf vor ' + (p02Alter / 3600).toFixed(1) + ' Stunden');
}

if (p03Alter === null || p03Alter > 691200) {
  fehler.push(p03Alter === null
    ? 'P03: kein erfolgreicher Vollabgleich vorhanden'
    : 'P03: letzter Vollabgleich vor ' + (p03Alter / 86400).toFixed(1) + ' Tagen');
}

if (zahl(r.offen_kosten) > 0)            fehler.push('Offene Kostenkonfigurationen: ' + r.offen_kosten);
if (zahl(r.date_ohne_offer) > 0)         fehler.push('Termine ohne Angebot: ' + r.date_ohne_offer);
if (zahl(r.position_ohne_buchung) > 0)   fehler.push('Buchungspositionen ohne Buchung: ' + r.position_ohne_buchung);
if (zahl(r.trans_ohne_buchung) > 0)      fehler.push('Buchungstransaktionen ohne Buchung: ' + r.trans_ohne_buchung);

if (zahl(r.buchung_ohne_offer) > 0)      warnungen.push('Buchungen ohne Angebot: ' + r.buchung_ohne_offer);
if (zahl(r.leader_ohne_trainer) > 0)     warnungen.push('Trainerzuordnungen ohne Trainerprofil (historisch): ' + r.leader_ohne_trainer);
if (zahl(r.attendance_ohne_termin) > 0)  warnungen.push('Anwesenheiten ohne Termin: ' + r.attendance_ohne_termin);
if (zahl(r.angebote_ohne_trainer) > 0)   warnungen.push('Produktive Angebote ohne Trainer: ' + r.angebote_ohne_trainer);

info.push(
  'DB-I (ab 2023): Netto ' + r.netto +
  ', Trainer ' + r.trainerkosten +
  ', Plattform ' + r.plattformkosten +
  ', direkte Kosten ' + r.direkte_kosten +
  ', DB I ' + r.db1 +
  ', berechenbare Angebote ' + r.berechenbare_angebote
);

const status = fehler.length ? 'fehler' : 'erfolgreich';
const bericht = ['P04-Kontrolle']
  .concat(fehler.map(function (f) { return 'FEHLER: ' + f; }))
  .concat(warnungen.map(function (w) { return 'WARNUNG: ' + w; }))
  .concat(info.map(function (i) { return 'INFO: ' + i; }))
  .join(' | ');

return [{
  json: {
    run_id: $('P04 Lauf anlegen').first().json.run_id,
    status,
    fehler: fehler.length,
    warnungen: warnungen.length,
    bericht,
    error_text: (fehler.length || warnungen.length) ? bericht.slice(0, 4000) : null,
  },
}];

// Holt alle Angebote seitenweise ueber GET /v2/offer/list.
// Angebote enthalten keine Personenangaben, deshalb wird die vollstaendige
// Antwort zusaetzlich als payload gesichert.

const auth = $('S16 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

function kennung(w) {
  // Manche Felder liefern eine Kennung als Text, andere ein Objekt.
  if (w === null || w === undefined || w === '') return null;
  if (typeof w === 'string' || typeof w === 'number') return String(w);
  if (typeof w === 'object') return w.id ? String(w.id) : null;
  return null;
}

function text(w) {
  if (w === null || w === undefined) return null;
  if (typeof w === 'string') return w;
  if (typeof w === 'number' || typeof w === 'boolean') return String(w);
  return null;
}

function ganzzahl(w) {
  const n = Number(w);
  return Number.isFinite(n) ? Math.trunc(n) : null;
}

function kommazahl(w) {
  if (w === null || w === undefined || w === '') return null;
  const n = Number(String(w).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function zeitpunkt(w) {
  const t = text(w);
  if (!t) return null;
  // Leere Platzhalter der Schnittstelle abfangen.
  if (/^0{4}-0{2}-0{2}/.test(t)) return null;
  return t;
}

function wahr(w) {
  if (w === true || w === 1 || w === '1' || w === 'true') return true;
  if (w === false || w === 0 || w === '0' || w === 'false' || w === '' || w === null || w === undefined) return false;
  return Boolean(w);
}

const basis = 'https://app1.edoobox.com/v2/offer/list';
const seitengroesse = 500;
const hoechstzahl_seiten = 30;

const gesammelt = new Map();
let abrufe = 0;
let gemeldet_total = null;
let versatz = 0;

for (let seite = 0; seite < hoechstzahl_seiten; seite += 1) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: basis,
    headers,
    qs: { 'limit[start]': versatz, 'limit[reply]': seitengroesse },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
  });
  abrufe += 1;

  if (antwort.statusCode !== 200) {
    throw new Error(`Seite ab ${versatz} lieferte Status ${antwort.statusCode}`);
  }

  const huelle = antwort.body?.limit ?? {};
  if (gemeldet_total === null) gemeldet_total = huelle.total ?? null;

  const roh = antwort.body?.data;
  const eintraege = Array.isArray(roh)
    ? roh.map((v, i) => [String(i), v])
    : roh && typeof roh === 'object'
      ? Object.entries(roh)
      : [];

  if (eintraege.length === 0) break;

  for (const [schluessel, satz] of eintraege) {
    const a = satz && typeof satz === 'object' ? satz : {};
    const id = kennung(a.id) ?? String(schluessel);
    if (!id) continue;

    gesammelt.set(id, {
      offer_id: id,
      offer_number: text(a.number),
      name: text(a.name),
      category_ref: kennung(a.category),
      offerdef_ref: kennung(a.offerdef),
      place_ref: kennung(a.place),
      date_start: zeitpunkt(a.date_start),
      date_end: zeitpunkt(a.date_end),
      date_signupstart: zeitpunkt(a.date_signupstart),
      date_close: zeitpunkt(a.date_close),
      user_minimal: ganzzahl(a.user_minimal),
      user_maximum: ganzzahl(a.user_maximum),
      status: text(a.status),
      mode: text(a.mode),
      offer_type: text(a.type),
      vat_rate: kommazahl(a.vat),
      country: text(a.country),
      internal_code: text(a.internal_code),
      is_archived: wahr(a.archive),
      is_trash: wahr(a.trash),
      has_waiting_list: wahr(a.waiting_list),
      mustpay: wahr(a.mustpay),
      is_multi_offer: wahr(a.multi_offer),
      is_multi_offer_child: wahr(a.multi_offer_child),
      payload: a,
    });
  }

  versatz += seitengroesse;
  if (gemeldet_total !== null && versatz >= gemeldet_total) break;
}

const saetze = [...gesammelt.values()];
const mit_start = saetze.filter((s) => s.date_start).length;

return [
  {
    json: {
      schritt: 'S16',
      run_id: $('S16 Lauf anlegen').first().json.run_id,
      gemeldet_total,
      eingesammelt: saetze.length,
      mit_startzeitpunkt: mit_start,
      abrufe,
      vollstaendig: gemeldet_total !== null ? saetze.length >= gemeldet_total : null,
      datenJson: JSON.stringify(saetze),
    },
  },
];

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const ids = $('S50 Buchungen auswaehlen').all().map(x => x.json.booking_id).filter(Boolean);
const geheim = /name|mail|email|phone|telefon|address|adresse|street|strasse|city|ort|zip|plz|note|bemerkung|password|token/i;

function eintraege(v) {
  if (v == null) return [];
  if (Array.isArray(v)) return v;
  if (typeof v === 'object') {
    const vals = Object.values(v);
    if (vals.length && vals.every(x => x && typeof x === 'object')) return vals;
    return [v];
  }
  return [v];
}
function feldbestand(obj) {
  if (!obj || typeof obj !== 'object') return `Werttyp ${typeof obj}`;
  return Object.entries(obj).map(([k,v]) => {
    if (geheim.test(k)) return `${k}=unterdrueckt`;
    if (v == null) return `${k}=leer`;
    if (Array.isArray(v)) return `${k}=Liste(${v.length})`;
    if (typeof v === 'object') return `${k}=Objekt(${Object.keys(v).length})`;
    return `${k}=${String(v).slice(0,80)}`;
  }).join(' | ');
}

const out = [];
for (const id of ids) {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2/booking/${encodeURIComponent(id)}/data`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 60000,
  });
  const raw = r.body?.data;
  const b = Array.isArray(raw) ? raw[0] : raw;
  if (!b || typeof b !== 'object') continue;

  const dates = eintraege(b.dates);
  out.push({json:{schritt:'S50', buchung:id, bereich:'dates', eintraege:dates.length,
    felder: dates.length ? feldbestand(dates[0]) : '-'}});

  const adminKeys = Object.keys(b).filter(k => /^admin/i.test(k));
  if (!adminKeys.length) {
    out.push({json:{schritt:'S50', buchung:id, bereich:'admin*', eintraege:0, felder:'kein Top-Level-Bereich'}});
  }
  for (const key of adminKeys) {
    const rows = eintraege(b[key]);
    out.push({json:{schritt:'S50', buchung:id, bereich:key, eintraege:rows.length,
      felder: rows.length ? feldbestand(rows[0]) : '-'}});
  }
}
out.push({json:{schritt:'S50', buchung:'KONTROLLE', bereich:'API-Abrufe', eintraege:ids.length,
  felder:'Nur Feldstruktur; Namen und Kontaktdaten unterdrueckt'}});
return out;

// Ermittelt den nutzbaren Endpunkt fuer die Buchungsliste.
// Es werden ausschliesslich Lesezugriffe ausgefuehrt.
// Ausgegeben werden nur Statuscodes und Feldnamen, keine Inhalte.

const auth = $input.first().json;
const token = auth.access_token;
const edid = auth?.data?.edid;

if (!token || !edid) {
  throw new Error('access_token oder edid fehlt in der Authentifizierungsantwort.');
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com';

const kandidaten = [
  { methode: 'GET',  url: `${basis}/v2/booking/list` },
  { methode: 'POST', url: `${basis}/v2/booking/list` },
  { methode: 'GET',  url: `${basis}/v2/bookings` },
  { methode: 'GET',  url: `${basis}/v1/bookings?language=de` },
];

function feldnamen(wert, tiefe = 0) {
  if (Array.isArray(wert)) {
    return {
      typ: 'array',
      anzahl: wert.length,
      erstes_element: wert.length && tiefe < 3 ? feldnamen(wert[0], tiefe + 1) : null,
    };
  }
  if (wert !== null && typeof wert === 'object') {
    if (tiefe >= 3) return { typ: 'object', felder: Object.keys(wert) };
    return Object.fromEntries(
      Object.entries(wert).slice(0, 40).map(([k, v]) => [k, feldnamen(v, tiefe + 1)])
    );
  }
  return { typ: wert === null ? 'null' : typeof wert };
}

const ergebnisse = [];

for (const kandidat of kandidaten) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: kandidat.methode,
      url: kandidat.url,
      headers,
      json: true,
      returnFullResponse: true,
      timeout: 20000,
    });

    ergebnisse.push({
      methode: kandidat.methode,
      url: kandidat.url,
      status: antwort.statusCode,
      brauchbar: antwort.statusCode >= 200 && antwort.statusCode < 300,
      struktur: feldnamen(antwort.body),
    });
  } catch (fehler) {
    ergebnisse.push({
      methode: kandidat.methode,
      url: kandidat.url,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      brauchbar: false,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 300),
    });
  }
}

const treffer = ergebnisse.filter((e) => e.brauchbar);

return [
  {
    json: {
      hinweis: 'Nur Statuscodes und Feldnamen. Keine Buchungsinhalte, keine Zugangsdaten.',
      gefundene_endpunkte: treffer.map((t) => `${t.methode} ${t.url}`),
      ergebnisse,
    },
  },
];

// Token aus beiden edoobox-Antwortformen ermitteln (analog P90).
const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token) {
  throw new Error('Kein Token in der edoobox-Auth-Antwort enthalten.');
}
const webhook = $('P96 Webhook').first().json;
// Der Webhook-Node legt den Request-Body unter 'body' ab. Die Payload-Felder
// (kdnr, firmenname, kursnr, start, ende, ...) werden deshalb flach uebernommen,
// damit die Folgeknoten sie direkt lesen koennen.
const payload = webhook.body || {};
const basis = payload.basis_url || auth.basis_url || 'https://app1.edoobox.com';
return [{ json: { ...payload, token, edid, basis } }];

// Kategorie-Handling:
//  1) Falls im Payload eine category_id (alternativ: category) uebergeben wurde:
//     pruefen, ob sie in edoobox existiert (GET /v2/category/{category_id}).
//  2) Existiert sie (HTTP 200): diese ID verwenden.
//  3) Existiert sie nicht (HTTP 404 oder Fehler):
//     a) Hauptkategorie 'Firmenkurse' ueber GET /v2/category/list suchen
//        (List-Endpunkt gemaess P90: '/category/list', Paginierung limit[start/reply]).
//     b) Unterkategorie '[kdnr] [Firmenname]' suchen, sonst unter 'Firmenkurse' anlegen.
//        GET listet die Elternkennung im Feld 'parent'; das ANLEGEN erwartet sie im
//        Feld 'category' (API-Hinweis ED80100: require { name, category, type }).
//  4) Ergebnis wird verlaesslich als category_id UND category an 'P96 Offer anlegen'
//     uebergeben (die urspruengliche Webhook-Kategorie wird ueberschrieben).
const state = $('P96 Token normalisieren').first().json;
const headers = {
  'Authorization': `Bearer ${state.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

function rowsAus(roh) {
  const d = roh && roh.data ? roh.data : roh;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

// 1) Uebergebene Kategorie (category_id bevorzugt, sonst category) pruefen
const eingang = state.category_id || state.category;
let categoryId = eingang ? String(eingang).trim() : null;
if (categoryId === '') categoryId = null;
if (categoryId) {
  const pruef = await this.helpers.httpRequest({
    method: 'GET',
    url: `${state.basis}/v2/category/${encodeURIComponent(categoryId)}`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });

  if (pruef.statusCode >= 200 && pruef.statusCode < 300 && !(pruef.body && pruef.body.success === false)) {
    // 2) Kategorie existiert -> uebergebene ID verwenden
    categoryId = String(categoryId);
  } else {
    // 3) HTTP 404 oder Fehler -> Kategorie neu ermitteln bzw. anlegen
    categoryId = null;
  }
}

if (!categoryId) {
  // 3a) Hauptkategorie 'Firmenkurse' ueber GET /v2/category/list suchen
  const listen = await this.helpers.httpRequest({
    method: 'GET',
    url: `${state.basis}/v2/category/list`,
    headers,
    qs: { 'limit[start]': 0, 'limit[reply]': 2000 },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });

  if (!(listen.statusCode >= 200 && listen.statusCode < 300)) {
    throw new Error('GET /v2/category/list: HTTP ' + listen.statusCode + ' - ' + JSON.stringify(listen.body).slice(0, 800));
  }

  const kategorien = rowsAus(listen.body);
  const haupt = kategorien.find((c) => (c.name || c.title) === 'Firmenkurse');
  if (!haupt) {
    throw new Error('Hauptkategorie Firmenkurse wurde nicht gefunden.');
  }
  const hauptId = haupt.id ?? haupt.category_id ?? haupt.ref;

  // 3b) Unterkategorie '[kdnr] [Firmenname]' suchen
  const unterName = `${state.kdnr} ${state.firmenname}`;
  const unter = kategorien.find((c) => (c.name || c.title) === unterName);
  categoryId = unter ? String(unter.id ?? unter.category_id ?? unter.ref) : null;

  // 3c) Nicht gefunden -> unter 'Firmenkurse' neu anlegen
  if (!categoryId) {
    const angelegt = await this.helpers.httpRequest({
      method: 'POST',
      url: `${state.basis}/v2/category`,
      headers,
      body: { data: { name: unterName, category: hauptId, type: 'folder' } },
      json: true,
      returnFullResponse: true,
      timeout: 120000,
      ignoreHttpStatusErrors: true,
    });

    if (!(angelegt.statusCode >= 200 && angelegt.statusCode < 300)) {
      throw new Error('POST /v2/category: HTTP ' + angelegt.statusCode + ' - ' + JSON.stringify(angelegt.body).slice(0, 800));
    }

    const ak = angelegt.body || {};
    if (ak.data && typeof ak.data === 'object') {
      categoryId = ak.data.id ?? ak.data.category_id ?? ak.data.ref;
    } else if (typeof ak.data === 'string' || typeof ak.data === 'number') {
      categoryId = ak.data;
    } else if (ak.category && typeof ak.category === 'object') {
      categoryId = ak.category.id ?? ak.category.category_id ?? ak.category.ref;
    } else {
      categoryId = ak.id ?? ak.category_id ?? ak.ref;
    }
    if (categoryId !== null && categoryId !== undefined) {
      categoryId = String(categoryId);
    }
  }
}

if (!categoryId) {
  throw new Error('Unterkategorie konnte nicht ermittelt oder angelegt werden.');
}

// 4) Aufgeloeste Kategorie in BEIDEN Feldern ablegen (ueberschreibt Webhook-Wert).
return [{ json: { ...state, category_id: String(categoryId), category: String(categoryId) } }];

// Angebot durch DUPLIZIEREN der Vorlage erzeugen und veroeffentlichen.
//  1) GET  /v2/offer/{sourceOfferId}             (Vorlage abrufen fuer Felddiagnose & Texte)
//  2) POST /v2/offer/{sourceOfferId}/duplicate   (Form-Data: name, category, type=offer, status=1)
//  3) GET  /v2/offer/{newOfferId}                (Verifikation status === 1)
const state = $input.first().json;
const basis = state.basis || 'https://app1.edoobox.com';

// 1. Feldnamen robust aufloesen
const sourceOfferId = state.sourceOfferId || state.template_offer_id || state.template_id;
const categoryId = String(state.category_id || state.category || '').trim();
const offerTitle = state.newTitle || state.kurstitel || state.vorlagen_name || state.thema || 'Neues Angebot';

if (!sourceOfferId) {
  throw new Error('Keine Quell-Angebots-ID (sourceOfferId / template_id) im State vorhanden.');
}
if (!categoryId) {
  throw new Error('Keine Kategorie-ID (category_id / category) im State vorhanden.');
}

const baseHeaders = {
  'Authorization': `Bearer ${state.token}`,
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

function parseBody(body) {
  if (typeof body === 'string') {
    try { return JSON.parse(body); } catch (e) { return body; }
  }
  return body;
}

// GET /v2/offer/{id} liefert { data: { <id>: { record } } } bzw. { data: [] }.
function entpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let d = body.data ?? body;
  while (d && typeof d === 'object' && !Array.isArray(d)) {
    const keys = Object.keys(d);
    if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
      d = d[keys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(d)) return d[0] ?? null;
  return d;
}

// Einheitlicher edoobox-Aufruf mit detaillierter Fehlerbehandlung
const edoobox = async (schritt, optionen) => {
  let antwort;
  try {
    antwort = await this.helpers.httpRequest({
      ...optionen,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 60000
    });
  } catch (error) {
    const status = error.response?.status ?? error.cause?.response?.status ?? error.statusCode ?? error.httpCode;
    const data = error.response?.data ?? error.cause?.response?.data ?? error.message;
    throw new Error(`edoobox Fehler [${status}] bei ${schritt}: ${JSON.stringify(data)}`);
  }
  const body = parseBody(antwort.body);
  const ok = antwort.statusCode >= 200 && antwort.statusCode < 300 && !(body && typeof body === 'object' && body.success === false);
  if (!ok) {
    throw new Error(`edoobox Fehler [${antwort.statusCode}] bei ${schritt}: ${JSON.stringify(body)}`);
  }
  return body;
};

try {
  // 1. Quell-Vorlage vorab abrufen (fuer Text- und Felddiagnose)
  const sourceGet = await edoobox(`GET /v2/offer/${sourceOfferId}`, {
    method: 'GET',
    url: `${basis}/v2/offer/${sourceOfferId}`,
    headers: { ...baseHeaders, 'Content-Type': 'application/json' },
    json: true
  });
  const sourceRoh = entpacken(sourceGet);

  // 2. Duplizieren via application/x-www-form-urlencoded mit status=1 (Veroeffentlicht)
  const bodyData = 'name=' + encodeURIComponent(offerTitle) +
                    '&category=' + encodeURIComponent(categoryId) +
                    '&type=offer' +
                    '&status=1';

  const dupBody = await edoobox(`POST /v2/offer/${sourceOfferId}/duplicate (category=${categoryId})`, {
    method: 'POST',
    url: `${basis}/v2/offer/${sourceOfferId}/duplicate`,
    headers: { ...baseHeaders, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: bodyData
  });

  const dupData = dupBody && (dupBody.data ?? dupBody.offer ?? dupBody);
  let newOfferId;
  if (typeof dupData === 'string' || typeof dupData === 'number') {
    newOfferId = dupData;
  } else {
    const rec = (dupData && (dupData.id ?? dupData.offer_id)) ? dupData : entpacken(dupBody);
    newOfferId = rec && (rec.id ?? rec.offer_id);
  }
  if (!newOfferId) {
    throw new Error('edoobox Fehler [2xx]: Duplizieren ohne neue Offer-ID, Antwort: ' + JSON.stringify(dupBody));
  }

  // 3. Zuruecklesen und Veroeffentlichung verifizieren (status === 1)
  const getBody = await edoobox(`GET /v2/offer/${newOfferId}`, {
    method: 'GET',
    url: `${basis}/v2/offer/${newOfferId}`,
    headers: { ...baseHeaders, 'Content-Type': 'application/json' },
    json: true
  });
  const offerRoh = entpacken(getBody);
  if (!offerRoh || Number(offerRoh.status) !== 1) {
    throw new Error('edoobox Fehler [verify]: Angebot ' + newOfferId + ' ist nicht veroeffentlicht (status=' + (offerRoh?.status) + '), Antwort: ' + JSON.stringify(getBody));
  }

  // 4. State fuer Folgeknoten anreichern (inklusive vollstaendiger Vorlagendaten)
  return [{
    json: {
      ...state,
      offer_id: String(newOfferId),
      published: true,
      offer: offerRoh,
      source_offer: sourceRoh
    }
  }];
} catch (error) {
  if (typeof error.message === 'string' && error.message.startsWith('edoobox Fehler')) {
    throw error;
  }
  throw new Error(`edoobox Fehler [${error.response?.status}]: ${JSON.stringify(error.response?.data ?? error.message)}`);
}

// Termin (Date) anlegen: Start/Ende, Trainer und einen kalendersprechenden Titel.
// EVENTUAL-CONSISTENCY-FIX: Der Offer wurde im vorherigen Knoten gerade erst
// angelegt. Ein unmittelbar folgender POST /v2/date kann bei edoobox mit
// HTTP 402 ED80100 abgelehnt werden, weil der frische Offer noch nicht
// vollstaendig indiziert ist. Deshalb Retry mit Backoff (bis zu 4 Versuche).
const zzState = $('P96 Offer anlegen').first().json;
const zzHeaders = {
  'Authorization': `Bearer ${zzState.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(zzState.edid ? { edid: zzState.edid } : {})
};

function zzEntpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let zzD = body.data ?? body;
  while (zzD && typeof zzD === 'object' && !Array.isArray(zzD)) {
    const zzKeys = Object.keys(zzD);
    if (zzKeys.length === 1 && zzD[zzKeys[0]] && typeof zzD[zzKeys[0]] === 'object') {
      zzD = zzD[zzKeys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(zzD)) return zzD[0] ?? null;
  return zzD;
}

const zzKurstitel = zzState.kurstitel || zzState.vorlagen_name || zzState.thema || '';
const zzTrainerKuerzel = (zzState.trainer_kuerzel || '').trim();
const zzTitle = zzTrainerKuerzel
  ? `${zzState.kdnr} ${zzKurstitel} (${zzTrainerKuerzel})`
  : [zzState.kdnr, zzKurstitel].filter(Boolean).join(' ');

const zzBody = {
  offer: zzState.offer_id,
  description: zzTitle,
  date_start: zzState.start,
  date_end: zzState.ende,
  place: false,
  room: false,
  leader: [zzState.trainer_admin_id]
};

// Retry-Loop (initial + 3 Wiederholungen). Rekursion ohne Top-Level-let.
async function zzDateAnlegen(zzVersuch) {
  const zzAntwort = await this.helpers.httpRequest({
    method: 'POST',
    url: `${zzState.basis}/v2/date`,
    headers: zzHeaders,
    body: { data: zzBody },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 60000
  });

  const zzOk = (zzAntwort.statusCode >= 200 && zzAntwort.statusCode < 300)
    && !(zzAntwort.body && zzAntwort.body.success === false);
  if (zzOk) return zzAntwort;

  const zzBodyText = JSON.stringify(zzAntwort.body).slice(0, 400);
  const zzRetryable = zzAntwort.statusCode === 402 || /ED80100/.test(zzBodyText);
  if (zzRetryable && zzVersuch < 4) {
    await new Promise((rr) => setTimeout(rr, zzVersuch * 1000));
    return zzDateAnlegen(zzVersuch + 1);
  }
  throw new Error('edoobox POST /v2/date: HTTP ' + zzAntwort.statusCode + ' - ' + zzBodyText);
}

const zzAntwortFinal = await zzDateAnlegen(1);

const zzRoh = zzAntwortFinal.body;
const zzNeu = zzRoh && (zzRoh.date ?? zzRoh.data ?? zzRoh);
const zzDateId = (zzNeu && (zzNeu.id ?? zzNeu.date_id)) || (zzRoh && zzRoh.data && zzRoh.data.id);
if (!zzDateId) {
  throw new Error('edoobox hat keine date_id zurueckgeliefert (Antwort: ' + JSON.stringify(zzRoh).slice(0, 500) + ')');
}

// Gezielter Einzel-Sync: nur diesen einen Termin zuruecklesen.
const zzGetAntwort = await this.helpers.httpRequest({
  method: 'GET',
  url: `${zzState.basis}/v2/date/${zzDateId}`,
  headers: zzHeaders,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 60000
});

if (!(zzGetAntwort.statusCode >= 200 && zzGetAntwort.statusCode < 300)) {
  throw new Error('edoobox GET /v2/date/' + zzDateId + ': HTTP ' + zzGetAntwort.statusCode + ' - ' + JSON.stringify(zzGetAntwort.body).slice(0, 1500));
}

const zzDateRoh = zzEntpacken(zzGetAntwort.body);

return [{ json: { offer_id: zzState.offer_id, date_id: String(zzDateId), offer: zzState.offer, offer_date: zzDateRoh } }];

// Holt die Buchungsdetails zu fuenf Buchungen und formt daraus
// Preiskategoriezeilen und Zahlungsvorgaenge.
// Personenbezogene Angaben wie Name, Anschrift, E-Mail und IP-Adresse
// werden bewusst nicht uebernommen.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const kennungen = $('S12 Buchungen auswaehlen')
  .all()
  .map((z) => z.json.booking_id)
  .filter(Boolean);

if (kennungen.length === 0) {
  throw new Error('Keine Buchungskennungen erhalten.');
}

function zahl(wert) {
  if (wert === null || wert === undefined || wert === '') return null;
  const n = Number(String(wert).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

const saetze = [];
const bericht = [];
let abrufe = 0;

for (const kennung of kennungen) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2/booking/${encodeURIComponent(kennung)}/data`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 60000,
  });
  abrufe += 1;

  const roh = antwort.body?.data;
  const b = Array.isArray(roh) ? roh[0] : roh && typeof roh === 'object' ? roh : {};

  bericht.push({
    buchung: kennung,
    status: antwort.statusCode,
    huellenfelder: Object.keys(antwort.body ?? {}).join(', '),
    detailfelder: Object.keys(b).join(', '),
    preiskategorien: b.pricecategory ? Object.keys(b.pricecategory).length : 0,
    zahlungen: Array.isArray(b.transactions) ? b.transactions.length : 0,
  });

  const waehrung =
    (Array.isArray(b.transactions) && b.transactions[0]?.currency) || b.promotion?.currency || 'EUR';

  const positionen = Object.entries(b.pricecategory ?? {}).map(([kategorieId, k]) => ({
    pricecategory_id: String(k?.id ?? kategorieId),
    pricecategory_name: String(k?.name ?? 'ohne Bezeichnung'),
    amount_net: zahl(k?.amount) ?? 0,
    currency: String(waehrung).slice(0, 3).toUpperCase(),
    quantity: Number.isFinite(Number(k?.count)) ? Number(k.count) : 1,
    is_default: k?.default === true,
  }));

  const vorgaenge = (Array.isArray(b.transactions) ? b.transactions : [])
    .filter((t) => t && t.id)
    .map((t) => ({
      transaction_id: String(t.id),
      transaction_number: t.number ? String(t.number) : null,
      amount: zahl(t.amount),
      currency: String(t.currency ?? waehrung)
        .slice(0, 3)
        .toUpperCase(),
      transaction_time: t.time ?? t.date ?? null,
    }));

  saetze.push({
    booking_id: String(kennung),
    is_b2b: b.invoice_address?.b2b === true,
    is_multi_offer: b.multi_offer === true,
    positionen,
    vorgaenge,
  });
}

return [
  {
    json: {
      schritt: 'S12',
      abrufe,
      buchungen: saetze.length,
      positionen_gesamt: saetze.reduce((s, x) => s + x.positionen.length, 0),
      vorgaenge_gesamt: saetze.reduce((s, x) => s + x.vorgaenge.length, 0),
      bericht,
      datenJson: JSON.stringify(saetze),
    },
  },
];

// Findet heraus, mit welchem Parameternamen sich der Versatz setzen laesst.
// Der Endpunkt spiegelt die verwendeten Werte im Huellenfeld limit zurueck,
// daran ist sofort erkennbar, ob ein Parameter angenommen wurde.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

function auswerten(body) {
  const roh = body?.data;
  const liste = roh && typeof roh === 'object' && !Array.isArray(roh) ? Object.entries(roh) : [];
  const ids = liste.map(([k, v]) => (v && typeof v === 'object' ? v.id ?? k : k));
  const l = body?.limit ?? {};
  return {
    anzahl: liste.length,
    gemeldet_start: l.start ?? '-',
    gemeldet_reply: l.reply ?? '-',
    gemeldet_total: l.total ?? '-',
    erste_id: ids[0] ?? null,
  };
}

async function abruf(bezeichnung, qs, url = basis) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers,
      qs,
      json: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    return { variante: bezeichnung, status: antwort.statusCode, ...auswerten(antwort.body) };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      anzahl: 0,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 160),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['A Grundabruf', {}],
  ['B start reply flach', { start: 100, reply: 10 }],
  ['C limit>start', { 'limit>start': 100, 'limit>reply': 10 }],
  ['D limit-start', { 'limit-start': 100, 'limit-reply': 10 }],
  ['E limit_start', { limit_start: 100, limit_reply: 10 }],
  ['F offset limit', { offset: 100, limit: 10 }],
  ['G page per_page', { page: 2, per_page: 10 }],
  ['H limit als Text', { limit: '100,10' }],
  ['I nur reply', { reply: 10 }],
  ['J Pfadangabe', {}, `${basis}/100/10`],
];

const ergebnisse = [];
for (const [bezeichnung, qs, url] of varianten) {
  ergebnisse.push(await hole(bezeichnung, qs, url));
}

const grund = ergebnisse[0];

return ergebnisse.map((e) => ({
  json: {
    schritt: 'S7',
    variante: e.variante,
    status: e.status,
    anzahl: e.anzahl,
    gemeldet_start: e.gemeldet_start ?? '-',
    gemeldet_reply: e.gemeldet_reply ?? '-',
    gemeldet_total: e.gemeldet_total ?? '-',
    parameter_wirkt:
      e.erste_id && grund?.erste_id ? (e.erste_id !== grund.erste_id ? 'JA' : 'nein') : '-',
    fehlermeldung: e.fehlermeldung ?? '-',
  },
}));

return [{
  workflowJson: Wetter Stundendaten
}];

// Ermittelt den nutzbaren Endpunkt fuer die Buchungsliste.
// Es werden ausschliesslich Lesezugriffe ausgefuehrt.
// Ausgegeben werden nur Statuscodes und Feldnamen, keine Inhalte.

const auth = $input.first().json;

// edoobox liefert je nach Server zwei Formen:
//   A) Token in 'data', edid auf oberster Ebene   (app1, aktuell)
//   B) Token in 'access_token', edid in 'data.edid' (Dokumentation V2)
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com';

const kandidaten = [
  { methode: 'GET',  url: `${basis}/v2/booking/list` },
  { methode: 'POST', url: `${basis}/v2/booking/list` },
  { methode: 'GET',  url: `${basis}/v2/bookings` },
  { methode: 'GET',  url: `${basis}/v1/bookings?language=de` },
];

function feldnamen(wert, tiefe = 0) {
  if (Array.isArray(wert)) {
    return {
      typ: 'array',
      anzahl: wert.length,
      erstes_element: wert.length && tiefe < 3 ? feldnamen(wert[0], tiefe + 1) : null,
    };
  }
  if (wert !== null && typeof wert === 'object') {
    if (tiefe >= 3) return { typ: 'object', felder: Object.keys(wert) };
    return Object.fromEntries(
      Object.entries(wert).slice(0, 40).map(([k, v]) => [k, feldnamen(v, tiefe + 1)])
    );
  }
  return { typ: wert === null ? 'null' : typeof wert };
}

const ergebnisse = [];

for (const kandidat of kandidaten) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: kandidat.methode,
      url: kandidat.url,
      headers,
      json: true,
      returnFullResponse: true,
      timeout: 20000,
    });

    ergebnisse.push({
      methode: kandidat.methode,
      url: kandidat.url,
      status: antwort.statusCode,
      brauchbar: antwort.statusCode >= 200 && antwort.statusCode < 300,
      struktur: feldnamen(antwort.body),
    });
  } catch (fehler) {
    ergebnisse.push({
      methode: kandidat.methode,
      url: kandidat.url,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      brauchbar: false,
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 300),
    });
  }
}

const treffer = ergebnisse.filter((e) => e.brauchbar);

return [
  {
    json: {
      schritt: 'S4 - Endpunktsuche',
      hinweis: 'Nur Statuscodes und Feldnamen. Keine Buchungsinhalte, keine Zugangsdaten.',
      erkannte_tokenform: typeof auth.data === 'string' ? 'Token in data' : 'Token in access_token',
      gefundene_endpunkte: treffer.map((t) => `${t.methode} ${t.url}`),
      ergebnisse,
    },
  },
];

// Prueft, wie sich die Buchungsliste blaettern laesst.
// Nur Lesezugriffe. Ausgegeben werden Anzahlen, Feldnamen und Buchungs-IDs.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const basis = 'https://app1.edoobox.com/v2/booking/list';

// Holt die eigentlichen Buchungssaetze heraus, egal ob
// Array oder Objekt mit IDs als Schluesseln.
function saetze(antwort) {
  const roh = antwort?.data ?? antwort;
  if (Array.isArray(roh)) {
    return { form: 'array', liste: roh.map((e, i) => ({ schluessel: String(i), wert: e })) };
  }
  if (roh && typeof roh === 'object') {
    return {
      form: 'objekt mit IDs als Schluessel',
      liste: Object.entries(roh).map(([k, v]) => ({ schluessel: k, wert: v })),
    };
  }
  return { form: 'unbekannt', liste: [] };
}

function kennung(eintrag) {
  const w = eintrag.wert;
  if (w && typeof w === 'object') {
    return w.id ?? w.booking ?? eintrag.schluessel;
  }
  return eintrag.schluessel;
}

async function abruf(bezeichnung, query) {
  try {
    const antwort = await this.helpers.httpRequest({
      method: 'GET',
      url: basis,
      headers,
      qs: query,
      json: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    const { form, liste } = saetze(antwort.body);
    return {
      variante: bezeichnung,
      parameter: query,
      status: antwort.statusCode,
      form,
      anzahl: liste.length,
      erste_ids: liste.slice(0, 3).map(kennung),
      letzte_id: liste.length ? kennung(liste[liste.length - 1]) : null,
      huellenfelder:
        antwort.body && typeof antwort.body === 'object' && !Array.isArray(antwort.body)
          ? Object.keys(antwort.body)
          : [],
      eintragsfelder:
        liste.length && liste[0].wert && typeof liste[0].wert === 'object'
          ? Object.keys(liste[0].wert)
          : [],
    };
  } catch (fehler) {
    return {
      variante: bezeichnung,
      parameter: query,
      status: fehler?.response?.status ?? fehler?.httpCode ?? 'kein Status',
      fehlermeldung: String(fehler?.message ?? fehler).slice(0, 300),
    };
  }
}

const hole = abruf.bind(this);

const varianten = [
  ['ohne Parameter', {}],
  ['eckige Klammern Seite 1', { 'limit[start]': 0, 'limit[reply]': 10, 'order[time]': 'DESC' }],
  ['eckige Klammern Seite 2', { 'limit[start]': 10, 'limit[reply]': 10, 'order[time]': 'DESC' }],
  ['punktschreibweise Seite 1', { 'limit.start': 0, 'limit.reply': 10, 'order.time': 'DESC' }],
  ['flach Seite 1', { start: 0, reply: 10, order: 'DESC' }],
];

const ergebnisse = [];
for (const [bezeichnung, query] of varianten) {
  ergebnisse.push(await hole(bezeichnung, query));
}

const mitDaten = ergebnisse.filter((e) => typeof e.anzahl === 'number' && e.anzahl > 0);
const seite1 = ergebnisse.find((e) => e.variante === 'eckige Klammern Seite 1');
const seite2 = ergebnisse.find((e) => e.variante === 'eckige Klammern Seite 2');
const ohne = ergebnisse.find((e) => e.variante === 'ohne Parameter');

let befund = 'unklar';
if (seite1?.anzahl && seite2?.anzahl) {
  const gleich = JSON.stringify(seite1.erste_ids) === JSON.stringify(seite2.erste_ids);
  befund = gleich
    ? 'Blaettern mit eckigen Klammern wirkt nicht, Seite 1 und Seite 2 sind identisch'
    : 'Blaettern mit eckigen Klammern funktioniert';
}

return [
  {
    json: {
      schritt: 'S5 - Blaetterlogik pruefen',
      hinweis: 'Nur Anzahlen, Feldnamen und Buchungs-IDs. Keine Namen, keine Betraege, keine Zugangsdaten.',
      befund,
      anzahl_ohne_parameter: ohne?.anzahl ?? null,
      varianten_mit_daten: mitDaten.map((e) => `${e.variante}: ${e.anzahl}`),
      ergebnisse,
    },
  },
];

// Token aus beiden edoobox-Antwortformen ermitteln (analog P90).
const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token) {
  throw new Error('Kein Token in der edoobox-Auth-Antwort enthalten.');
}
const webhook = $('P96 Webhook').first().json;
// Der Webhook-Node legt den Request-Body unter 'body' ab. Die Payload-Felder
// (kdnr, firmenname, kursnr, start, ende, ...) werden deshalb flach uebernommen,
// damit die Folgeknoten sie direkt lesen koennen.
const payload = webhook.body || {};
const basis = payload.basis_url || auth.basis_url || 'https://app1.edoobox.com';
return [{ json: { ...payload, token, edid, basis } }];

// Kategorie-Handling:
//  1) Falls im Payload eine category_id (alternativ: category) uebergeben wurde:
//     pruefen, ob sie in edoobox existiert (GET /v2/category/{category_id}).
//  2) Existiert sie (HTTP 200): diese ID verwenden.
//  3) Existiert sie nicht (HTTP 404 oder Fehler):
//     a) Hauptkategorie 'Firmenkurse' ueber GET /v2/category/list suchen
//        (List-Endpunkt gemaess P90: '/category/list', Paginierung limit[start/reply]).
//     b) Unterkategorie '[kdnr] [Firmenname]' suchen, sonst unter 'Firmenkurse' anlegen.
//        GET listet die Elternkennung im Feld 'parent'; das ANLEGEN erwartet sie im
//        Feld 'category' (API-Hinweis ED80100: require { name, category, type }).
//  4) Ergebnis wird verlaesslich als category_id UND category an 'P96 Offer anlegen'
//     uebergeben (die urspruengliche Webhook-Kategorie wird ueberschrieben).
const state = $('P96 Token normalisieren').first().json;
const headers = {
  'Authorization': `Bearer ${state.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

function rowsAus(roh) {
  const d = roh && roh.data ? roh.data : roh;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

// 1) Uebergebene Kategorie (category_id bevorzugt, sonst category) pruefen
const eingang = state.category_id || state.category;
let categoryId = eingang ? String(eingang).trim() : null;
if (categoryId === '') categoryId = null;
if (categoryId) {
  const pruef = await this.helpers.httpRequest({
    method: 'GET',
    url: `${state.basis}/v2/category/${encodeURIComponent(categoryId)}`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });

  if (pruef.statusCode >= 200 && pruef.statusCode < 300 && !(pruef.body && pruef.body.success === false)) {
    // 2) Kategorie existiert -> uebergebene ID verwenden
    categoryId = String(categoryId);
  } else {
    // 3) HTTP 404 oder Fehler -> Kategorie neu ermitteln bzw. anlegen
    categoryId = null;
  }
}

if (!categoryId) {
  // 3a) Hauptkategorie 'Firmenkurse' ueber GET /v2/category/list suchen
  const listen = await this.helpers.httpRequest({
    method: 'GET',
    url: `${state.basis}/v2/category/list`,
    headers,
    qs: { 'limit[start]': 0, 'limit[reply]': 2000 },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });

  if (!(listen.statusCode >= 200 && listen.statusCode < 300)) {
    throw new Error('GET /v2/category/list: HTTP ' + listen.statusCode + ' - ' + JSON.stringify(listen.body).slice(0, 800));
  }

  const kategorien = rowsAus(listen.body);
  const haupt = kategorien.find((c) => (c.name || c.title) === 'Firmenkurse');
  if (!haupt) {
    throw new Error('Hauptkategorie Firmenkurse wurde nicht gefunden.');
  }
  const hauptId = haupt.id ?? haupt.category_id ?? haupt.ref;

  // 3b) Unterkategorie '[kdnr] [Firmenname]' suchen
  const unterName = `${state.kdnr} ${state.firmenname}`;
  const unter = kategorien.find((c) => (c.name || c.title) === unterName);
  categoryId = unter ? String(unter.id ?? unter.category_id ?? unter.ref) : null;

  // 3c) Nicht gefunden -> unter 'Firmenkurse' neu anlegen
  if (!categoryId) {
    const angelegt = await this.helpers.httpRequest({
      method: 'POST',
      url: `${state.basis}/v2/category`,
      headers,
      body: { data: { name: unterName, category: hauptId, type: 'folder' } },
      json: true,
      returnFullResponse: true,
      timeout: 120000,
      ignoreHttpStatusErrors: true,
    });

    if (!(angelegt.statusCode >= 200 && angelegt.statusCode < 300)) {
      throw new Error('POST /v2/category: HTTP ' + angelegt.statusCode + ' - ' + JSON.stringify(angelegt.body).slice(0, 800));
    }

    const ak = angelegt.body || {};
    if (ak.data && typeof ak.data === 'object') {
      categoryId = ak.data.id ?? ak.data.category_id ?? ak.data.ref;
    } else if (typeof ak.data === 'string' || typeof ak.data === 'number') {
      categoryId = ak.data;
    } else if (ak.category && typeof ak.category === 'object') {
      categoryId = ak.category.id ?? ak.category.category_id ?? ak.category.ref;
    } else {
      categoryId = ak.id ?? ak.category_id ?? ak.ref;
    }
    if (categoryId !== null && categoryId !== undefined) {
      categoryId = String(categoryId);
    }
  }
}

if (!categoryId) {
  throw new Error('Unterkategorie konnte nicht ermittelt oder angelegt werden.');
}

// 4) Aufgeloeste Kategorie in BEIDEN Feldern ablegen (ueberschreibt Webhook-Wert).
return [{ json: { ...state, category_id: String(categoryId), category: String(categoryId) } }];

// Angebot durch DUPLIZIEREN der Vorlage erzeugen und veroeffentlichen.
//  1) POST /v2/offer/{template_id}/duplicate  (Form-Data: name, category, type=offer, status=2)
//  2) GET  /v2/offer/{newOfferId}             (Verifikation status === 2)
// WICHTIG: Ein nachgelagerter PUT /v2/offer/{id} mit status liefert bei edoobox
// HTTP 200 + {error: ED90100, success: false} - der Status laesst sich NUR beim
// Anlegen setzen (status=2 => veroeffentlicht, 0 => Entwurf). Deshalb status=2
// direkt im Duplicate-Body.
// Jeder edoobox-Fehler wird mit dem EXAKTEN Antwort-Body als Error geworfen:
//   edoobox Fehler [<status>] ...: <JSON-Body>
const state = $input.first().json;
const basis = state.basis || 'https://app1.edoobox.com';

// 1. Feldnamen robust aufloesen
const sourceOfferId = state.sourceOfferId || state.template_offer_id || state.template_id;
const categoryId = String(state.category_id || state.category || '').trim();
const offerTitle = state.newTitle || state.kurstitel || state.vorlagen_name || state.thema || 'Neues Angebot';

if (!sourceOfferId) {
  throw new Error('Keine Quell-Angebots-ID (sourceOfferId / template_id) im State vorhanden.');
}
if (!categoryId) {
  throw new Error('Keine Kategorie-ID (category_id / category) im State vorhanden.');
}

const baseHeaders = {
  'Authorization': `Bearer ${state.token}`,
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

function parseBody(body) {
  if (typeof body === 'string') {
    try { return JSON.parse(body); } catch (e) { return body; }
  }
  return body;
}

// GET /v2/offer/{id} liefert { data: { <id>: { record } } } bzw. { data: [] }.
function entpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let d = body.data ?? body;
  while (d && typeof d === 'object' && !Array.isArray(d)) {
    const keys = Object.keys(d);
    if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
      d = d[keys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(d)) return d[0] ?? null;
  return d;
}

// Einheitlicher edoobox-Aufruf: HTTP-Status und Antwort-Body werden immer
// ausgewertet; bei Fehlern wird der exakte Body im Error-Text ausgegeben.
const edoobox = async (schritt, optionen) => {
  let antwort;
  try {
    antwort = await this.helpers.httpRequest({
      ...optionen,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 60000
    });
  } catch (error) {
    const status = error.response?.status ?? error.cause?.response?.status ?? error.statusCode ?? error.httpCode;
    const data = error.response?.data ?? error.cause?.response?.data ?? error.message;
    throw new Error(`edoobox Fehler [${status}] bei ${schritt}: ${JSON.stringify(data)}`);
  }
  const body = parseBody(antwort.body);
  const ok = antwort.statusCode >= 200 && antwort.statusCode < 300 && !(body && typeof body === 'object' && body.success === false);
  if (!ok) {
    throw new Error(`edoobox Fehler [${antwort.statusCode}] bei ${schritt}: ${JSON.stringify(body)}`);
  }
  return body;
};

try {
  // 2. Duplizieren via application/x-www-form-urlencoded
  const bodyData = 'name=' + encodeURIComponent(offerTitle) +
                   '&category=' + encodeURIComponent(categoryId) +
                   '&type=offer' +
                   '&status=2';

  const dupBody = await edoobox(`POST /v2/offer/${sourceOfferId}/duplicate (category=${categoryId})`, {
    method: 'POST',
    url: `${basis}/v2/offer/${sourceOfferId}/duplicate`,
    headers: { ...baseHeaders, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: bodyData
  });

  const dupData = dupBody && (dupBody.data ?? dupBody.offer ?? dupBody);
  let newOfferId;
  if (typeof dupData === 'string' || typeof dupData === 'number') {
    newOfferId = dupData;
  } else {
    const rec = (dupData && (dupData.id ?? dupData.offer_id)) ? dupData : entpacken(dupBody);
    newOfferId = rec && (rec.id ?? rec.offer_id);
  }
  if (!newOfferId) {
    throw new Error('edoobox Fehler [2xx]: Duplizieren ohne neue Offer-ID, Antwort: ' + JSON.stringify(dupBody));
  }

  // 4. Zuruecklesen und Veroeffentlichung verifizieren
  const getBody = await edoobox(`GET /v2/offer/${newOfferId}`, {
    method: 'GET',
    url: `${basis}/v2/offer/${newOfferId}`,
    headers: { ...baseHeaders, 'Content-Type': 'application/json' },
    json: true
  });
  const offerRoh = entpacken(getBody);
  if (!offerRoh || Number(offerRoh.status) !== 2) {
    throw new Error('edoobox Fehler [verify]: Angebot ' + newOfferId + ' ist nicht veroeffentlicht, Antwort: ' + JSON.stringify(getBody));
  }

  // 5. State fuer Folgeknoten (P96 Date anlegen) anreichern
  return [{
    json: {
      ...state,
      offer_id: String(newOfferId),
      published: true,
      offer: offerRoh
    }
  }];
} catch (error) {
  if (typeof error.message === 'string' && error.message.startsWith('edoobox Fehler')) {
    throw error;
  }
  throw new Error(`edoobox Fehler [${error.response?.status}]: ${JSON.stringify(error.response?.data ?? error.message)}`);
}

// Termin (Date) anlegen: Start/Ende, Trainer und einen kalendersprechenden Titel.
// EVENTUAL-CONSISTENCY-FIX: Der Offer wurde im vorherigen Knoten gerade erst
// angelegt. Ein unmittelbar folgender POST /v2/date kann bei edoobox mit
// HTTP 402 ED80100 abgelehnt werden, weil der frische Offer noch nicht
// vollstaendig indiziert ist. Deshalb Retry mit Backoff (bis zu 4 Versuche).
const zzState = $('P96 Offer anlegen').first().json;
const zzHeaders = {
  'Authorization': `Bearer ${zzState.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(zzState.edid ? { edid: zzState.edid } : {})
};

function zzEntpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let zzD = body.data ?? body;
  while (zzD && typeof zzD === 'object' && !Array.isArray(zzD)) {
    const zzKeys = Object.keys(zzD);
    if (zzKeys.length === 1 && zzD[zzKeys[0]] && typeof zzD[zzKeys[0]] === 'object') {
      zzD = zzD[zzKeys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(zzD)) return zzD[0] ?? null;
  return zzD;
}

const zzKurstitel = zzState.kurstitel || zzState.vorlagen_name || zzState.thema || '';
const zzTrainerKuerzel = (zzState.trainer_kuerzel || '').trim();
const zzTitle = zzTrainerKuerzel
  ? `${zzState.kdnr} ${zzKurstitel} (${zzTrainerKuerzel})`
  : [zzState.kdnr, zzKurstitel].filter(Boolean).join(' ');

const zzBody = {
  offer: zzState.offer_id,
  description: zzTitle,
  date_start: zzState.start,
  date_end: zzState.ende,
  place: false,
  room: false,
  leader: [zzState.trainer_admin_id]
};

// Retry-Loop (initial + 3 Wiederholungen). Rekursion ohne Top-Level-let.
async function zzDateAnlegen(zzVersuch) {
  const zzAntwort = await this.helpers.httpRequest({
    method: 'POST',
    url: `${zzState.basis}/v2/date`,
    headers: zzHeaders,
    body: { data: zzBody },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 60000
  });

  const zzOk = (zzAntwort.statusCode >= 200 && zzAntwort.statusCode < 300)
    && !(zzAntwort.body && zzAntwort.body.success === false);
  if (zzOk) return zzAntwort;

  const zzBodyText = JSON.stringify(zzAntwort.body).slice(0, 400);
  const zzRetryable = zzAntwort.statusCode === 402 || /ED80100/.test(zzBodyText);
  if (zzRetryable && zzVersuch < 4) {
    await new Promise((rr) => setTimeout(rr, zzVersuch * 1000));
    return zzDateAnlegen(zzVersuch + 1);
  }
  throw new Error('edoobox POST /v2/date: HTTP ' + zzAntwort.statusCode + ' - ' + zzBodyText);
}

const zzAntwortFinal = await zzDateAnlegen(1);

const zzRoh = zzAntwortFinal.body;
const zzNeu = zzRoh && (zzRoh.date ?? zzRoh.data ?? zzRoh);
const zzDateId = (zzNeu && (zzNeu.id ?? zzNeu.date_id)) || (zzRoh && zzRoh.data && zzRoh.data.id);
if (!zzDateId) {
  throw new Error('edoobox hat keine date_id zurueckgeliefert (Antwort: ' + JSON.stringify(zzRoh).slice(0, 500) + ')');
}

// Gezielter Einzel-Sync: nur diesen einen Termin zuruecklesen.
const zzGetAntwort = await this.helpers.httpRequest({
  method: 'GET',
  url: `${zzState.basis}/v2/date/${zzDateId}`,
  headers: zzHeaders,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 60000
});

if (!(zzGetAntwort.statusCode >= 200 && zzGetAntwort.statusCode < 300)) {
  throw new Error('edoobox GET /v2/date/' + zzDateId + ': HTTP ' + zzGetAntwort.statusCode + ' - ' + JSON.stringify(zzGetAntwort.body).slice(0, 1500));
}

const zzDateRoh = zzEntpacken(zzGetAntwort.body);

return [{ json: { offer_id: zzState.offer_id, date_id: String(zzDateId), offer: zzState.offer, offer_date: zzDateRoh } }];

// Holt alle Rechnungen und gibt nur die Kennungen und Betraege weiter.
// Es wird nichts geschrieben. Der Vergleich findet in der Datenbank statt.

const auth = $('S23 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

async function seite(start) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://app1.edoobox.com/v2/invoice/list',
    headers,
    qs: { 'limit[start]': start, 'limit[reply]': 2000 },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });
}

const hole = seite.bind(this);

const alle = [];
let start = 0;
let abrufe = 0;

while (abrufe < 20) {
  const antwort = await hole(start);
  abrufe += 1;
  if (antwort.statusCode !== 200) {
    throw new Error(`Rechnungsliste Status ${antwort.statusCode} bei start ${start}`);
  }
  const h = antwort.body && typeof antwort.body === 'object' ? antwort.body : {};
  const d = Array.isArray(h.data) ? h.data : h.data && typeof h.data === 'object' ? Object.values(h.data) : [];
  alle.push(...d);
  if (d.length < 2000) break;
  start += 2000;
}

function zahl(wert) {
  if (wert === null || wert === undefined || wert === '' || wert === false) return null;
  const n = Number(String(wert).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function zeitpunkt(wert) {
  if (typeof wert !== 'string') return null;
  return /^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(wert) ? wert : null;
}

const saetze = alle
  .filter((r) => r && r.id)
  .map((r) => ({
    invoice_id: String(r.id),
    paytrans: r.paytrans ? String(r.paytrans) : null,
    user_ref: r.user ? String(r.user) : null,
    invoice_number: r.number ? String(r.number) : null,
    amount: zahl(r.amount),
    currency: String(r.currency ?? 'EUR').slice(0, 3).toUpperCase(),
    status: zahl(r.status),
    date_create: zeitpunkt(r.date_create),
    date_pay: zeitpunkt(r.date_pay),
    date_payuntil: zeitpunkt(r.date_payuntil),
    date_cancelled: zeitpunkt(r.date_cancelled),
    offer_start_date: zeitpunkt(r.offer_start_date),
  }));

return [{
  json: {
    schritt: 'S23',
    rechnungen: saetze.length,
    abrufe,
    laenge_paytrans: [...new Set(saetze.map((s) => (s.paytrans ?? '').length))].sort((a, b) => a - b).join(', '),
    laenge_user: [...new Set(saetze.map((s) => (s.user_ref ?? '').length))].sort((a, b) => a - b).join(', '),
    datenJson: JSON.stringify(saetze),
  },
}];

