// Token aus beiden edoobox-Antwortformen ermitteln (analog P90).
const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token) {
  throw new Error('Kein Token in der edoobox-Auth-Antwort enthalten.');
}
const webhook = $('P96 Webhook').first().json;
// Der Webhook-Node legt den Request-Body unter 'body' ab. Die Payload-Felder
// (kdnr, firmenname, kursnr, start, ende, ...) werden deshalb flach uebernommen,
// damit die Folgeknoten sie direkt lesen koennen.
const payload = webhook.body || {};
const basis = payload.basis_url || auth.basis_url || 'https://app1.edoobox.com';
return [{ json: { ...payload, token, edid, basis } }];

// Kategorie-Handling:
//  1) Hauptkategorie 'Firmenkurse' ueber GET /v2/category/list suchen
//     (List-Endpunkt gemaess P90: '/category/list', Paginierung limit[start/reply]).
//  2) Unterkategorie '[kdnr] [Firmenname]' pruefen, sonst unter 'Firmenkurse' anlegen.
//     GET listet die Elternkennung im Feld 'parent'; das ANLEGEN erwartet sie im
//     Feld 'category' (API-Hinweis ED80100: require { name, category, type }).
const state = $('P96 Token normalisieren').first().json;
const headers = {
  'Authorization': `Bearer ${state.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

function rowsAus(roh) {
  const d = roh && roh.data ? roh.data : roh;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

const listen = await this.helpers.httpRequest({
  method: 'GET',
  url: `${state.basis}/v2/category/list`,
  headers,
  qs: { 'limit[start]': 0, 'limit[reply]': 2000 },
  json: true,
  returnFullResponse: true,
  timeout: 120000,
  ignoreHttpStatusErrors: true,
});

if (!(listen.statusCode >= 200 && listen.statusCode < 300)) {
  throw new Error('GET /v2/category/list: HTTP ' + listen.statusCode + ' - ' + JSON.stringify(listen.body).slice(0, 800));
}

const kategorien = rowsAus(listen.body);
const haupt = kategorien.find((c) => (c.name || c.title) === 'Firmenkurse');
if (!haupt) {
  throw new Error('Hauptkategorie Firmenkurse wurde nicht gefunden.');
}
const hauptId = haupt.id ?? haupt.category_id ?? haupt.ref;

const unterName = `${state.kdnr} ${state.firmenname}`;
const unter = kategorien.find((c) => (c.name || c.title) === unterName);
let categoryId = unter ? (unter.id ?? unter.category_id ?? unter.ref) : null;

if (!categoryId) {
  const angelegt = await this.helpers.httpRequest({
    method: 'POST',
    url: `${state.basis}/v2/category`,
    headers,
    body: { data: { name: unterName, category: hauptId, type: 'folder' } },
    json: true,
    returnFullResponse: true,
    timeout: 120000,
    ignoreHttpStatusErrors: true,
  });

  if (!(angelegt.statusCode >= 200 && angelegt.statusCode < 300)) {
    throw new Error('POST /v2/category: HTTP ' + angelegt.statusCode + ' - ' + JSON.stringify(angelegt.body).slice(0, 800));
  }

  const ak = angelegt.body || {};
  if (ak.data && typeof ak.data === 'object') {
    categoryId = ak.data.id ?? ak.data.category_id ?? ak.data.ref;
  } else if (typeof ak.data === 'string' || typeof ak.data === 'number') {
    categoryId = ak.data;
  } else if (ak.category && typeof ak.category === 'object') {
    categoryId = ak.category.id ?? ak.category.category_id ?? ak.category.ref;
  } else {
    categoryId = ak.id ?? ak.category_id ?? ak.ref;
  }
}

if (!categoryId) {
  throw new Error('Unterkategorie konnte nicht ermittelt oder angelegt werden.');
}

return [{ json: { ...state, category_id: String(categoryId) } }];

// Angebot unter der ermittelten Unterkategorie anlegen und DIREKT veroeffentlichen.
// edoobox V2 POST /v2/offer erwartet den Nutzdatensatz im Wrapper { "data": {...} }.
// Pflichtfelder laut API-Referenz: category, name, number, type.
//
// VEROEFFENTLICHUNG (hart verifiziert anhand des gespiegelten Bestands):
// Das Statusfeld heisst "status" und ist numerisch:
//   status = 0  => "Entwurf"
//   status = 1  => "Veröffentlicht"
//   status = 2  => "Garantierte Durchführung"
//   status = 3/4/5 => abgeschlossen/archiviert
// Beleg: Die korrekt veroeffentlichten Firmenkurse "2250-pbi-gl-1026" und
// "2250-xls-gl-m2-0926" tragen status = '1'. Das fruehere status=2 erzeugte
// fälschlich "Garantierte Durchführung". Deshalb status: 1 und Verifikation == 1.
//
// PREISE (Vorlagen-Klon):
// edoobox erzeugt bei POST /v2/offer automatisch genau EINE Standard-Preiskategorie
// (Name "---"). Diese kann per DELETE nicht entfernt werden (HTTP 404 ED80019) und
// per PUT nicht umbenannt werden (PUT akzeptiert laut API-Doku nur amount/status/order,
// kein name). Deshalb gilt folgende Strategie:
//   1) ALLE Vorlagenpreise per POST /v2/pricecategory anlegen (korrekte Namen).
//   2) Die auto-erzeugte Standardkategorie (initial_price_id) per DELETE entfernen;
//      bei Fehlschlag per PUT status=false deaktivieren.
//
// Felder der Preisstruktur "pricecategory":
//   name, amount, offer, order, status, default, customer_limit, date_start, date_end
//
// Ablauf:
//   1) GET /v2/pricecategory/list?filter=[{property:"offer",expression:"=",value:<template_id>}]
//      -> templatePrices (Vorlage)
//   2) GET /v2/pricecategory/list?filter=[{property:"offer",expression:"=",value:<offer_id>}]
//      -> vorhandene (automatisch erzeugte) Preiskategorien des neuen Offers
//   3) Alle templatePrices per POST anlegen.
//   4) initial_price_id (erste vorhandene Kategorie) per DELETE entfernen;
//      bei Fehlschlag per PUT status=false deaktivieren.
const state = $('P96 Kategorien verarbeiten').first().json;
const headers = {
  'Authorization': `Bearer ${state.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(state.edid ? { edid: state.edid } : {})
};

// GET /v2/offer/{id} (und /v2/date/{id}) liefern { data: { <id>: { record } } }
// bzw. { data: [] }. Diese Helferfunktion entpackt die Kennungs-Ebene.
function entpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let d = body.data ?? body;
  while (d && typeof d === 'object' && !Array.isArray(d)) {
    const keys = Object.keys(d);
    if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
      d = d[keys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(d)) return d[0] ?? null;
  return d;
}

// Liste aus einer List-Antwort extrahieren (data kann Objekt oder Array sein).
function listeAus(body) {
  if (!body || typeof body !== 'object') return [];
  let d = body.data ?? body;
  while (d && typeof d === 'object' && !Array.isArray(d)) {
    const keys = Object.keys(d);
    // { data: { <preis_id>: { record } } } -> Werte aufsammeln
    if (keys.length >= 1 && keys.every((k) => d[k] && typeof d[k] === 'object')) {
      return Object.values(d);
    }
    if (keys.length === 1 && d[keys[0]] && typeof d[keys[0]] === 'object') {
      d = d[keys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(d)) return d;
  return [];
}

// Preiskategorie-ID aus einem Datensatz ermitteln.
function preisIdAus(kat) {
  return kat && (kat.id ?? kat.pricecategory_id ?? kat.ref);
}

// Kopierbare Felder aus einem Vorlagen-Preis extrahieren (ohne offer).
function felderAus(kat) {
  return {
    name: kat.name ?? kat.title ?? null,
    amount: kat.amount ?? kat.amount_net ?? null,
    ...(kat.order !== undefined && kat.order !== null && kat.order !== false ? { order: kat.order } : {}),
    ...(kat.status !== undefined && kat.status !== null ? { status: kat.status } : {}),
    ...(kat.default !== undefined && kat.default !== null ? { default: kat.default } : {}),
    ...(kat.customer_limit !== undefined && kat.customer_limit !== null ? { customer_limit: kat.customer_limit } : {}),
    ...(kat.date_start !== undefined && kat.date_start !== null && kat.date_start !== false ? { date_start: kat.date_start } : {}),
    ...(kat.date_end !== undefined && kat.date_end !== null && kat.date_end !== false ? { date_end: kat.date_end } : {})
  };
}

const daten = {
  category: state.category_id,
  name: state.vorlagen_name || state.thema,
  number: state.kursnr,
  type: 'offer',
  status: 1,
  mode: 'Online',
  country: 'country_d31aa3310f9b_4934995030',
  vat: 'dynamic',
  ...(state.offerdef_ref ? { offerdef: state.offerdef_ref } : {}),
  ...(state.user_minimal !== null && state.user_minimal !== undefined ? { user_minimal: state.user_minimal } : {}),
  ...(state.user_maximum !== null && state.user_maximum !== undefined ? { user_maximum: state.user_maximum } : {}),
  ...(state.anmeldeschluss ? { date_close: state.anmeldeschluss } : {})
};

const antwort = await this.helpers.httpRequest({
  method: 'POST',
  url: `${state.basis}/v2/offer`,
  headers,
  body: { data: daten },
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 60000
});

if (!(antwort.statusCode >= 200 && antwort.statusCode < 300) || (antwort.body && antwort.body.success === false)) {
  throw new Error('edoobox POST /v2/offer: HTTP ' + antwort.statusCode + ' - ' + JSON.stringify(antwort.body).slice(0, 1500));
}

const roh = antwort.body;
const neu = roh && (roh.offer ?? roh.data ?? roh);
const offerId = (neu && (neu.id ?? neu.offer_id)) || (roh && roh.data && roh.data.id);
if (!offerId) {
  throw new Error('edoobox hat keine offer_id zurueckgeliefert (Antwort: ' + JSON.stringify(roh).slice(0, 500) + ')');
}

// ---------------------------------------------------------------------------
// PREISE aus dem Vorlagen-Angebot (Template) uebernehmen.
// ---------------------------------------------------------------------------
const templateId = state.template_id;
const templateOfferId = state.template_offer_id || templateId;
let preiseKopiert = 0;
let standardpreisEntfernt = 0;
if (templateOfferId) {
  try {
    // 1) Vorlagenpreise abrufen.
    const preisListe = await this.helpers.httpRequest({
      method: 'GET',
      url: `${state.basis}/v2/pricecategory/list`,
      headers,
      qs: {
        'filter': JSON.stringify([{ property: 'offer', expression: '=', value: templateOfferId }]),
        'limit[start]': 0,
        'limit[reply]': 200
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 60000
    });

    if (!(preisListe.statusCode >= 200 && preisListe.statusCode < 300)) {
      throw new Error('GET /v2/pricecategory/list (Template): HTTP ' + preisListe.statusCode);
    }

    const templatePrices = listeAus(preisListe.body)
      .filter((kat) => kat && typeof kat === 'object')
      .filter((kat) => {
        const name = kat.name ?? kat.title;
        const amount = kat.amount ?? kat.amount_net;
        return !(name === null || name === undefined || amount === null || amount === undefined);
      });

    // 2) Aktuelle Preiskategorien des neuen Offers abrufen (auto-erzeugte Standardzeile).
    const neuListe = await this.helpers.httpRequest({
      method: 'GET',
      url: `${state.basis}/v2/pricecategory/list`,
      headers,
      qs: {
        'filter': JSON.stringify([{ property: 'offer', expression: '=', value: String(offerId) }]),
        'limit[start]': 0,
        'limit[reply]': 200
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 60000
    });

    let bestehende = [];
    if (neuListe.statusCode >= 200 && neuListe.statusCode < 300) {
      bestehende = listeAus(neuListe.body).filter((kat) => kat && typeof kat === 'object');
    }

    // initial_price_id = erste vorhandene Preiskategorie (die von edoobox erzeugte).
    const erste = bestehende.find((kat) => preisIdAus(kat));
    const initialPriceId = erste ? preisIdAus(erste) : null;

    // 3) ALLE Vorlagenpreise per POST anlegen (korrekte Namen).
    for (const kat of templatePrices) {
      const neuerPreis = { ...felderAus(kat), offer: String(offerId) };
      const preisAntwort = await this.helpers.httpRequest({
        method: 'POST',
        url: `${state.basis}/v2/pricecategory`,
        headers,
        body: { data: neuerPreis },
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 60000
      });
      if (preisAntwort.statusCode >= 200 && preisAntwort.statusCode < 300) {
        preiseKopiert += 1;
      } else {
        console.log('Warnung: POST /v2/pricecategory fehlgeschlagen (HTTP ' + preisAntwort.statusCode + '): ' + JSON.stringify(preisAntwort.body).slice(0, 300));
      }
    }

    // 4) Auto-erzeugte Standardkategorie entfernen: DELETE, Fallback PUT status=false.
    if (initialPriceId) {
      const delAntwort = await this.helpers.httpRequest({
        method: 'DELETE',
        url: `${state.basis}/v2/pricecategory/${initialPriceId}`,
        headers,
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 60000
      });
      if (delAntwort.statusCode >= 200 && delAntwort.statusCode < 300) {
        standardpreisEntfernt += 1;
        console.log('Standardpreis ' + initialPriceId + ' per DELETE entfernt (HTTP ' + delAntwort.statusCode + ')');
      } else {
        // DELETE nicht unterstuetzt (HTTP 404 ED80019) -> deaktivieren.
        const putAntwort = await this.helpers.httpRequest({
          method: 'PUT',
          url: `${state.basis}/v2/pricecategory/${initialPriceId}`,
          headers,
          body: { data: { status: false, default: false } },
          json: true,
          returnFullResponse: true,
          ignoreHttpStatusErrors: true,
          timeout: 60000
        });
        if (putAntwort.statusCode >= 200 && putAntwort.statusCode < 300) {
          standardpreisEntfernt += 1;
          console.log('Standardpreis ' + initialPriceId + ' deaktiviert (PUT status=false, HTTP ' + putAntwort.statusCode + ')');
        } else {
          console.log('Warnung: Standardpreis ' + initialPriceId + ' weder loesch- noch deaktivierbar (DELETE ' + delAntwort.statusCode + ' / PUT ' + putAntwort.statusCode + ')');
        }
      }
    }
  } catch (e) {
    console.log('Warnung: Preisuebernahme aus Template fehlgeschlagen: ' + e.message);
  }
}

// BILD uebernehmen: publicfile-ID aus image.name (CDN-Name) ermitteln und per
// PUT /v2/offer/{id}/image setzen. Das image-Objekt kommt 1:1 aus dem Template
// (state.image) ueber die App-Route.
const templateImage = state.image != null && typeof state.image === 'object'
  && !Array.isArray(state.image) ? state.image : null;
if (templateImage && templateImage.name) {
  const cdnName = String(templateImage.name).replace(/^aws\|\|/, '');
  let publicfileId = templateImage.publicfile ?? templateImage.public_file ?? null;
  if (!publicfileId && cdnName) {
    try {
      const pfList = await this.helpers.httpRequest({
        method: 'GET',
        url: `${state.basis}/v2/publicfile`,
        headers,
        qs: { 'limit[start]': 0, 'limit[reply]': 2000 },
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 60000
      });
      if (pfList.statusCode >= 200 && pfList.statusCode < 300) {
        const pfData = pfList.body && pfList.body.data ? pfList.body.data : pfList.body;
        if (pfData && typeof pfData === 'object') {
          for (const [pid, pf] of Object.entries(pfData)) {
            if (pf && (pf.file_name_cdn === cdnName || pf.file_name === cdnName)) {
              publicfileId = pid;
              break;
            }
          }
        }
      }
    } catch (e) {
      console.log('Warnung: GET /v2/publicfile fehlgeschlagen: ' + e.message);
    }
  }
  if (publicfileId) {
    const imgAntwort = await this.helpers.httpRequest({
      method: 'PUT',
      url: `${state.basis}/v2/offer/${offerId}/image`,
      headers,
      body: { data: { publicfile: publicfileId } },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 60000
    });
    if (!(imgAntwort.statusCode >= 200 && imgAntwort.statusCode < 300)) {
      console.log('Warnung: PUT /v2/offer/' + offerId + '/image schlug fehl (HTTP ' + imgAntwort.statusCode + '): ' + JSON.stringify(imgAntwort.body).slice(0, 300));
    }
  }
}

// Gezielter Einzel-Sync: Datensatz zuruecklesen und Veroeffentlichung verifizieren.
const getAntwort = await this.helpers.httpRequest({
  method: 'GET',
  url: `${state.basis}/v2/offer/${offerId}`,
  headers,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 60000
});

if (!(getAntwort.statusCode >= 200 && getAntwort.statusCode < 300)) {
  throw new Error('edoobox GET /v2/offer/' + offerId + ': HTTP ' + getAntwort.statusCode + ' - ' + JSON.stringify(getAntwort.body).slice(0, 1500));
}

const offerRoh = entpacken(getAntwort.body);
const veroeffentlicht = offerRoh && Number(offerRoh.status) === 1;
if (!veroeffentlicht) {
  throw new Error('edoobox hat das Angebot nicht auf "veroeffentlicht" gesetzt (status=' + JSON.stringify(offerRoh && offerRoh.status) + ')');
}

return [{ json: { ...state, offer_id: String(offerId), published: true, preise_kopiert: preiseKopiert, standardpreis_entfernt: standardpreisEntfernt, offer: offerRoh } }];

// Termin (Date) anlegen: Start/Ende, Trainer und einen kalendersprechenden Titel.
// EVENTUAL-CONSISTENCY-FIX: Der Offer wurde im vorherigen Knoten gerade erst
// angelegt. Ein unmittelbar folgender POST /v2/date kann bei edoobox mit
// HTTP 402 ED80100 abgelehnt werden, weil der frische Offer noch nicht
// vollstaendig indiziert ist. Deshalb Retry mit Backoff (bis zu 4 Versuche).
const zzState = $('P96 Offer anlegen').first().json;
const zzHeaders = {
  'Authorization': `Bearer ${zzState.token}`,
  'Content-Type': 'application/json',
  'grant-type': 'access_token',
  ...(zzState.edid ? { edid: zzState.edid } : {})
};

function zzEntpacken(body) {
  if (!body || typeof body !== 'object') return body;
  let zzD = body.data ?? body;
  while (zzD && typeof zzD === 'object' && !Array.isArray(zzD)) {
    const zzKeys = Object.keys(zzD);
    if (zzKeys.length === 1 && zzD[zzKeys[0]] && typeof zzD[zzKeys[0]] === 'object') {
      zzD = zzD[zzKeys[0]];
      continue;
    }
    break;
  }
  if (Array.isArray(zzD)) return zzD[0] ?? null;
  return zzD;
}

const zzKurstitel = zzState.kurstitel || zzState.vorlagen_name || zzState.thema || '';
const zzTrainerKuerzel = (zzState.trainer_kuerzel || '').trim();
const zzTitle = zzTrainerKuerzel
  ? `${zzState.kdnr} ${zzKurstitel} (${zzTrainerKuerzel})`
  : [zzState.kdnr, zzKurstitel].filter(Boolean).join(' ');

const zzBody = {
  offer: zzState.offer_id,
  description: zzTitle,
  date_start: zzState.start,
  date_end: zzState.ende,
  place: false,
  room: false,
  leader: [zzState.trainer_admin_id]
};

// Retry-Loop (initial + 3 Wiederholungen). Rekursion ohne Top-Level-let.
async function zzDateAnlegen(zzVersuch) {
  const zzAntwort = await this.helpers.httpRequest({
    method: 'POST',
    url: `${zzState.basis}/v2/date`,
    headers: zzHeaders,
    body: { data: zzBody },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 60000
  });

  const zzOk = (zzAntwort.statusCode >= 200 && zzAntwort.statusCode < 300)
    && !(zzAntwort.body && zzAntwort.body.success === false);
  if (zzOk) return zzAntwort;

  const zzBodyText = JSON.stringify(zzAntwort.body).slice(0, 400);
  const zzRetryable = zzAntwort.statusCode === 402 || /ED80100/.test(zzBodyText);
  if (zzRetryable && zzVersuch < 4) {
    await new Promise((rr) => setTimeout(rr, zzVersuch * 1000));
    return zzDateAnlegen(zzVersuch + 1);
  }
  throw new Error('edoobox POST /v2/date: HTTP ' + zzAntwort.statusCode + ' - ' + zzBodyText);
}

const zzAntwortFinal = await zzDateAnlegen(1);

const zzRoh = zzAntwortFinal.body;
const zzNeu = zzRoh && (zzRoh.date ?? zzRoh.data ?? zzRoh);
const zzDateId = (zzNeu && (zzNeu.id ?? zzNeu.date_id)) || (zzRoh && zzRoh.data && zzRoh.data.id);
if (!zzDateId) {
  throw new Error('edoobox hat keine date_id zurueckgeliefert (Antwort: ' + JSON.stringify(zzRoh).slice(0, 500) + ')');
}

// Gezielter Einzel-Sync: nur diesen einen Termin zuruecklesen.
const zzGetAntwort = await this.helpers.httpRequest({
  method: 'GET',
  url: `${zzState.basis}/v2/date/${zzDateId}`,
  headers: zzHeaders,
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  timeout: 60000
});

if (!(zzGetAntwort.statusCode >= 200 && zzGetAntwort.statusCode < 300)) {
  throw new Error('edoobox GET /v2/date/' + zzDateId + ': HTTP ' + zzGetAntwort.statusCode + ' - ' + JSON.stringify(zzGetAntwort.body).slice(0, 1500));
}

const zzDateRoh = zzEntpacken(zzGetAntwort.body);

return [{ json: { offer_id: zzState.offer_id, date_id: String(zzDateId), offer: zzState.offer, offer_date: zzDateRoh } }];

// Holt die Detailangaben aller offenen Buchungen in einem Durchgang.
// Die Ausgabe wird in Pakete zerlegt, damit der nachfolgende
// Datenbankknoten je Paket einmal laeuft und keine Riesenanweisung entsteht.

const auth = $('S20 Token holen').first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const kennungen = $input.all().map((z) => z.json.booking_id).filter(Boolean);

if (kennungen.length === 0) {
  return [];
}

function zahl(wert) {
  if (wert === null || wert === undefined || wert === '') return null;
  const n = Number(String(wert).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}

function aktiv(u) {
  // Die Schnittstelle liefert active als Wahrheitswert, Zahl oder Text.
  const w = u?.active;
  return w === true || w === 1 || w === '1' || w === 'true';
}

async function einzeln(kennung) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2/booking/${encodeURIComponent(kennung)}/data`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 60000,
    ignoreHttpStatusErrors: true,
  });

  if (antwort.statusCode !== 200) {
    return { booking_id: String(kennung), fehler: `Status ${antwort.statusCode}` };
  }

  const roh = antwort.body?.data;
  const b = Array.isArray(roh) ? roh[0] : roh && typeof roh === 'object' ? roh : {};

  const waehrung = (Array.isArray(b.transactions) && b.transactions[0]?.currency) || 'EUR';

  // Nur aktive Teilnehmer zaehlen. Abgemeldete Eintraege bleiben in der
  // Liste stehen und wuerden die Auslastung sonst ueber 100 Prozent treiben.
  const alle = Array.isArray(b.users) ? b.users : [];
  const aktive = alle.filter(aktiv);

  const je_kategorie = {};
  for (const u of aktive) {
    const k = u?.pricecategory ? String(u.pricecategory) : null;
    if (!k) continue;
    je_kategorie[k] = (je_kategorie[k] ?? 0) + 1;
  }

  const positionen = Object.entries(b.pricecategory ?? {}).map(([kategorieId, k]) => {
    const id = String(k?.id ?? kategorieId);
    const gemeldet = Number.isFinite(Number(k?.count)) ? Number(k.count) : null;
    const gezaehlt = je_kategorie[id] ?? null;
    return {
      pricecategory_id: id,
      pricecategory_name: String(k?.name ?? 'ohne Bezeichnung'),
      amount_net: zahl(k?.amount) ?? 0,
      currency: String(waehrung).slice(0, 3).toUpperCase(),
      quantity: gezaehlt !== null && gezaehlt > 0 ? gezaehlt : (gemeldet ?? 0),
      is_default: k?.default === true,
    };
  });

  const vorgaenge = (Array.isArray(b.transactions) ? b.transactions : [])
    .filter((t) => t && t.id)
    .map((t) => ({
      transaction_id: String(t.id),
      transaction_number: t.number ? String(t.number) : null,
      amount: zahl(t.amount),
      currency: String(t.currency ?? waehrung).slice(0, 3).toUpperCase(),
    }));

  return {
    booking_id: String(kennung),
    offer_id: b.offer ? String(b.offer) : null,
    is_b2b: b.invoice_address?.b2b === true,
    is_multi_offer: b.multi_offer === true,
    teilnehmer_aktiv: aktive.length,
    teilnehmer_gesamt: alle.length,
    positionen,
    vorgaenge,
  };
}

const holen = einzeln.bind(this);

const gleichzeitig = 8;
const saetze = [];
const fehler = [];

for (let i = 0; i < kennungen.length; i += gleichzeitig) {
  const gruppe = kennungen.slice(i, i + gleichzeitig);
  const ergebnisse = await Promise.all(gruppe.map((k) => holen(k)));
  for (const e of ergebnisse) {
    if (e.fehler) fehler.push(`${e.booking_id}: ${e.fehler}`);
    else saetze.push(e);
  }
}

// In Schreibpakete zerlegen. Der Datenbankknoten laeuft je Paket einmal.
const paketgroesse = 400;
const pakete = [];

for (let i = 0; i < kennungen.length; i += paketgroesse) {
  const kennungspaket = kennungen.slice(i, i + paketgroesse);
  const menge = new Set(kennungspaket.map(String));
  const datenpaket = saetze.filter((s) => menge.has(s.booking_id));

  pakete.push({
    json: {
      schritt: 'S20',
      paket: pakete.length + 1,
      buchungen_im_paket: kennungspaket.length,
      erfolgreich: datenpaket.length,
      fehlerhaft_gesamt: fehler.length,
      fehlerliste: fehler.slice(0, 10),
      alleKennungenJson: JSON.stringify(kennungspaket.map((k) => ({ booking_id: String(k) }))),
      datenJson: JSON.stringify(datenpaket),
    },
  });
}

return pakete;

// Liest drei Buchungsdetails und meldet nur den Feldbestand der
// verschachtelten Bereiche, keine Klardaten. Werte werden ausschliesslich
// dann gezeigt, wenn sie erkennbar keine Personenangabe sind: Zahlen,
// Wahrheitswerte und Zeitangaben.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;

if (!token || !edid) {
  throw new Error('Token oder edid nicht gefunden. Vorhandene Felder: ' + Object.keys(auth).join(', '));
}

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};

const kennungen = $('S13 Buchungen auswaehlen')
  .all()
  .map((z) => z.json.booking_id)
  .filter(Boolean);

// Bereiche, die fuer Termine, Kurszuordnung und Zahlungen wichtig sind.
const bereiche = ['transactions', 'payments', 'fees', 'dates', 'offer', 'promotion', 'lessons_booking', 'users'];

// Feldnamen, die niemals ausgegeben werden.
const gesperrt = /name|vorname|nachname|mail|street|strasse|address|adresse|city|ort|zip|plz|phone|tel|ip|birth|geburt|company|firma|salut|anrede|title|land|country|note|bemerkung/i;

function typBezeichnung(w) {
  if (w === null || w === undefined) return 'leer';
  if (Array.isArray(w)) return `Liste(${w.length})`;
  if (typeof w === 'object') return `Objekt(${Object.keys(w).length})`;
  return typeof w;
}

function beispielwert(schluessel, w) {
  if (gesperrt.test(schluessel)) return 'unterdrueckt';
  if (w === null || w === undefined) return null;
  if (typeof w === 'boolean' || typeof w === 'number') return w;
  if (typeof w === 'string') {
    // Nur unverfaengliche Formen zeigen: Zahlen, Datum, Zeit, Kennungen.
    if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(w)) return w;
    if (/^[0-9]+([.,][0-9]+)?$/.test(w)) return w;
    if (/^[a-z_]+_[0-9a-f]{8,}/i.test(w)) return w.slice(0, 40);
    return `Text(${w.length})`;
  }
  return typBezeichnung(w);
}

function felder(objekt) {
  if (!objekt || typeof objekt !== 'object') return [];
  return Object.entries(objekt).map(([k, v]) => ({
    feld: k,
    typ: typBezeichnung(v),
    beispiel: beispielwert(k, v),
  }));
}

const zeilen = [];
let abrufe = 0;

for (const kennung of kennungen) {
  const antwort = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://app1.edoobox.com/v2/booking/${encodeURIComponent(kennung)}/data`,
    headers,
    json: true,
    returnFullResponse: true,
    timeout: 60000,
  });
  abrufe += 1;

  const roh = antwort.body?.data;
  const b = Array.isArray(roh) ? roh[0] : roh && typeof roh === 'object' ? roh : {};
  const kurz = String(kennung).slice(0, 28);

  for (const bereich of bereiche) {
    const inhalt = b[bereich];

    if (inhalt === null || inhalt === undefined) {
      zeilen.push({ schritt: 'S13', buchung: kurz, bereich, form: 'fehlt', eintraege: 0, felder: '' });
      continue;
    }

    // Erstes Element bestimmen, egal ob Liste oder Objekt mit Kennungen.
    let erstes = inhalt;
    let anzahl = 1;
    let form = 'Objekt';

    if (Array.isArray(inhalt)) {
      form = 'Liste';
      anzahl = inhalt.length;
      erstes = inhalt[0];
    } else if (typeof inhalt === 'object') {
      const werte = Object.values(inhalt);
      const alleObjekte = werte.length > 0 && werte.every((v) => v && typeof v === 'object' && !Array.isArray(v));
      if (alleObjekte) {
        form = 'Objekt mit Kennungen';
        anzahl = werte.length;
        erstes = werte[0];
      }
    }

    if (anzahl === 0 || !erstes || typeof erstes !== 'object') {
      zeilen.push({ schritt: 'S13', buchung: kurz, bereich, form, eintraege: anzahl, felder: '' });
      continue;
    }

    zeilen.push({
      schritt: 'S13',
      buchung: kurz,
      bereich,
      form,
      eintraege: anzahl,
      felder: felder(erstes)
        .map((f) => `${f.feld}=${f.typ}${f.beispiel === null || f.beispiel === undefined ? '' : ' [' + f.beispiel + ']'}`)
        .join(' | '),
    });
  }
}

zeilen.push({ schritt: 'S13', buchung: 'ZUSAMMENFASSUNG', bereich: 'abrufe', form: '', eintraege: abrufe, felder: '' });

return zeilen.map((z) => ({ json: z }));
